INSERT INTO `interview_questions` (`id`, `interview_id`, `question_id`, `question_order`, `question_snapshot`, `created_at`) VALUES
(1, 1, 301, 1, '{\"question_text\":\"Что такое Image Map?\",\"answers\":[]}', '2026-05-13 15:23:18'),
(2, 1, 313, 2, '{\"question_text\":\"Что такое элемент <canvas>?\",\"answers\":[]}', '2026-05-13 15:23:18'),
(3, 1, 327, 3, '{\"question_text\":\"Разница между тегами <progress> и <meter>?\",\"answers\":[]}', '2026-05-13 15:23:18'),
(4, 1, 308, 4, '{\"question_text\":\"Сколько тегов <main> может быть на странице?\",\"answers\":[]}', '2026-05-13 15:23:19'),
(5, 1, 329, 5, '{\"question_text\":\"Что такое ARIA-роли (role=\\\"...\\\")?\",\"answers\":[]}', '2026-05-13 15:23:19'),
(6, 1, 332, 6, '{\"question_text\":\"Что такое \\\"Схлопывание границ\\\" в контексте чистого HTML?\",\"answers\":[]}', '2026-05-13 15:23:19'),
(7, 1, 333, 7, '{\"question_text\":\"Что такое атрибуты async и defer для тега <script>?\",\"answers\":[]}', '2026-05-13 15:23:19'),
(15, 3, 6, 1, '{\"question_text\":\"Какие виды строк есть в Python 3?\",\"answers\":[{\"id\":21,\"answer\":\"Только тип str (Юникод), для байтов используется тип bytes\"},{\"id\":22,\"answer\":\"Два типа: str для обычного текста и unicode для спецсимволов\"},{\"id\":23,\"answer\":\"Только ASCII строки, Юникод поддерживается только через библиотеки\"},{\"id\":24,\"answer\":\"Строки делятся на изменяемые и неизменяемые в зависимости от кавычек\"}]}', '2026-05-13 16:43:41'),
(16, 3, 10, 2, '{\"question_text\":\"Что такое диапазон (range)?\",\"answers\":[{\"id\":37,\"answer\":\"Неизменяемая последовательность чисел, которая вычисляется лениво\"},{\"id\":38,\"answer\":\"Список, который хранит абсолютно все числа от старта до финиша\"},{\"id\":39,\"answer\":\"Функция для генерации случайных чисел в заданном промежутке\"},{\"id\":40,\"answer\":\"Метод для автоматического расширения размера списка\"}]}', '2026-05-13 16:43:41'),
(17, 3, 5, 3, '{\"question_text\":\"Что такое последовательность (Sequence)?\",\"answers\":[{\"id\":17,\"answer\":\"Итерабельный объект, поддерживающий доступ по индексу и знающий свою длину\"},{\"id\":18,\"answer\":\"Любой объект, который был создан внутри цикла for\"},{\"id\":19,\"answer\":\"Функция, которая вызывает саму себя бесконечное количество раз\"},{\"id\":20,\"answer\":\"Список, содержащий только элементы одного и того же типа\"}]}', '2026-05-13 16:43:42'),
(18, 3, 23, 4, '{\"question_text\":\"Где быстрее поиск: в списке или в словаре?\",\"answers\":[{\"id\":89,\"answer\":\"В словаре поиск O(1), в списке O(n), поэтому словарь быстрее\"},{\"id\":90,\"answer\":\"В списке, так как это упорядоченная последовательность\"},{\"id\":91,\"answer\":\"Скорость одинаковая, так как оба объекта хранятся в куче\"},{\"id\":92,\"answer\":\"В списке, если он отсортирован по возрастанию\"}]}', '2026-05-13 16:43:42'),
(19, 3, 47, 5, '{\"question_text\":\"Можно ли извлечь элемент генератора по индексу?\",\"answers\":[{\"id\":185,\"answer\":\"Нет, генераторы поддерживают только последовательный перебор\"},{\"id\":186,\"answer\":\"Да, если генератор содержит только числа типа int\"},{\"id\":187,\"answer\":\"Да, с помощью встроенного метода .get_item()\"},{\"id\":188,\"answer\":\"Только если генератор был создан через списковое включение\"}]}', '2026-05-13 16:43:42'),
(20, 3, 7, 6, '{\"question_text\":\"Можно ли изменить символ в строке по индексу?\",\"answers\":[{\"id\":25,\"answer\":\"Нет, строки в Python являются неизменяемыми (immutable)\"},{\"id\":26,\"answer\":\"Да, если использовать двойные кавычки вместо одинарных\"},{\"id\":27,\"answer\":\"Да, с помощью метода .replace_at(index, char)\"},{\"id\":28,\"answer\":\"Только если строка содержит только латинские символы\"}]}', '2026-05-13 16:43:42'),
(21, 3, 24, 7, '{\"question_text\":\"В чем разница между *args и **kwargs?\",\"answers\":[{\"id\":93,\"answer\":\"*args — кортеж позиционных аргументов, **kwargs — словарь именованных\"},{\"id\":94,\"answer\":\"*args используется в классах, а **kwargs только в обычных функциях\"},{\"id\":95,\"answer\":\"*args — это список, а **kwargs — это неизменяемый кортеж\"},{\"id\":96,\"answer\":\"Разницы нет, это два названия для одного и того же механизма\"}]}', '2026-05-13 16:43:42'),
(22, 3, 61, 8, '{\"question_text\":\"Что такое виртуальное окружение (venv)?\",\"answers\":[{\"id\":241,\"answer\":\"Изолированная папка с интерпретатором и библиотеками для конкретного проекта\"},{\"id\":242,\"answer\":\"Облачное хранилище для исходного кода на серверах GitHub\"},{\"id\":243,\"answer\":\"Специальный режим Windows для запуска Linux-приложений\"},{\"id\":244,\"answer\":\"Программа для удаленного управления рабочим столом другого программиста\"}]}', '2026-05-13 16:43:42'),
(23, 3, 18, 9, '{\"question_text\":\"Что такое множество (set)?\",\"answers\":[{\"id\":69,\"answer\":\"Неупорядоченная коллекция уникальных хешируемых объектов\"},{\"id\":70,\"answer\":\"Список, который автоматически сортируется при добавлении элемента\"},{\"id\":71,\"answer\":\"Словарь, в котором ключи всегда являются строками\"},{\"id\":72,\"answer\":\"Массив фиксированной длины для хранения целых чисел\"}]}', '2026-05-13 16:43:42'),
(24, 3, 14, 10, '{\"question_text\":\"Чем список (list) отличается от кортежа (tuple)?\",\"answers\":[{\"id\":53,\"answer\":\"Списки изменяемы (mutable), кортежи — нет (immutable)\"},{\"id\":54,\"answer\":\"В списках можно хранить только числа, а в кортежах — что угодно\"},{\"id\":55,\"answer\":\"Списки работают быстрее кортежей в 10 раз\"},{\"id\":56,\"answer\":\"Кортежи нельзя передавать в качестве аргументов функций\"}]}', '2026-05-13 16:43:42'),
(55, 7, 12, 1, '{\"question_text\":\"Чем отличаются globals() и locals()?\",\"answers\":[{\"id\":45,\"answer\":\"globals() — словарь переменных модуля, locals() — текущей области (функции)\"},{\"id\":46,\"answer\":\"globals() — переменные системы Windows, locals() — только приложения\"},{\"id\":47,\"answer\":\"globals() возвращает список, а locals() всегда возвращает кортеж\"},{\"id\":48,\"answer\":\"Ничем не отличаются, это псевдонимы одной и той же функции\"}]}', '2026-05-15 08:08:58'),
(56, 7, 41, 2, '{\"question_text\":\"Что такое итерабельный объект (Iterable)?\",\"answers\":[{\"id\":161,\"answer\":\"Объект, способный возвращать элементы по одному (имеет __iter__ или __getitem__)\"},{\"id\":162,\"answer\":\"Любая переменная, которая была использована внутри цикла while\"},{\"id\":163,\"answer\":\"Функция, которая возвращает результат с помощью ключевого слова return\"},{\"id\":164,\"answer\":\"Объект, который можно вывести в консоль через функцию print()\"}]}', '2026-05-15 08:08:58'),
(57, 7, 31, 3, '{\"question_text\":\"Что такое \\\"объект первого класса\\\"?\",\"answers\":[{\"id\":121,\"answer\":\"Объект, который можно передать в функцию, вернуть из неё или присвоить переменной\"},{\"id\":122,\"answer\":\"Встроенный тип данных, имеющий наивысший приоритет в памяти\"},{\"id\":123,\"answer\":\"Класс, от которого наследуются все остальные классы в проекте\"},{\"id\":124,\"answer\":\"Глобальная переменная, доступная из любого модуля программы\"}]}', '2026-05-15 08:08:58'),
(58, 7, 25, 4, '{\"question_text\":\"Почему нельзя использовать mutable объект как default value?\",\"answers\":[{\"id\":97,\"answer\":\"Объект создается один раз при определении функции и разделяется между вызовами\"},{\"id\":98,\"answer\":\"Это приведет к немедленной ошибке SyntaxError при запуске кода\"},{\"id\":99,\"answer\":\"Mutable объекты занимают слишком много места в стеке вызовов\"},{\"id\":100,\"answer\":\"Функция не сможет вернуть результат, если в ней есть изменяемый объект\"}]}', '2026-05-15 08:08:58'),
(59, 7, 37, 5, '{\"question_text\":\"Разница между _var и __var?\",\"answers\":[{\"id\":145,\"answer\":\"_var — соглашение о приватности, __var — запуск name mangling для защиты имени\"},{\"id\":146,\"answer\":\"_var доступна только в текущем модуле, а __var — во всем проекте\"},{\"id\":147,\"answer\":\"__var автоматически делает переменную числовой, а _var — строковой\"},{\"id\":148,\"answer\":\"Никакой разницы нет, это просто разные стили написания кода\"}]}', '2026-05-15 08:08:59'),
(60, 7, 71, 6, '{\"question_text\":\"Зачем нужен pdb?\",\"answers\":[{\"id\":281,\"answer\":\"Для интерактивной отладки кода, установки брейкпоинтов и анализа переменных\"},{\"id\":282,\"answer\":\"Для хранения паролей и секретных ключей внутри Python-проекта\"},{\"id\":283,\"answer\":\"Специальный плагин для ускорения работы сервера Django в 2 раза\"},{\"id\":284,\"answer\":\"Формат файлов для упаковки бинарных зависимостей в Linux\"}]}', '2026-05-15 08:08:59'),
(61, 7, 11, 7, '{\"question_text\":\"Что такое \\\"утиная типизация\\\" (Duck Typing)?\",\"answers\":[{\"id\":41,\"answer\":\"Принцип: если объект имеет нужные методы, его класс не имеет значения\"},{\"id\":42,\"answer\":\"Ошибка, когда интерпретатор путает типы данных в сложных циклах\"},{\"id\":43,\"answer\":\"Специальный синтаксис для создания классов, наследуемых от птиц\"},{\"id\":44,\"answer\":\"Способ оптимизации памяти для очень маленьких объектов\"}]}', '2026-05-15 08:08:59'),
(62, 7, 66, 8, '{\"question_text\":\"Что такое Unit-тест?\",\"answers\":[{\"id\":261,\"answer\":\"Тестирование минимальной части кода в полной изоляции от внешних систем\"},{\"id\":262,\"answer\":\"Проверка работы всего приложения с точки зрения конечного пользователя\"},{\"id\":263,\"answer\":\"Тест, который проверяет только скорость работы базы данных под нагрузкой\"},{\"id\":264,\"answer\":\"Автоматическая проверка кода на наличие грамматических ошибок в комментариях\"}]}', '2026-05-15 08:08:59'),
(63, 7, 43, 9, '{\"question_text\":\"Чем генератор отличается от списка?\",\"answers\":[{\"id\":169,\"answer\":\"Генератор вычисляет элементы лениво и не хранит их все в памяти сразу\"},{\"id\":170,\"answer\":\"Генератор может хранить только числа, а список — любые типы данных\"},{\"id\":171,\"answer\":\"Списки нельзя использовать в циклах for, а генераторы — можно\"},{\"id\":172,\"answer\":\"Генераторы автоматически сортируют элементы при их создании\"}]}', '2026-05-15 08:08:59'),
(64, 7, 26, 10, '{\"question_text\":\"Что такое лямбда-функция?\",\"answers\":[{\"id\":101,\"answer\":\"Анонимная функция, состоящая из одного единственного выражения\"},{\"id\":102,\"answer\":\"Функция, которая автоматически удаляется после первого вызова\"},{\"id\":103,\"answer\":\"Специальный метод класса для работы с математическими вычислениями\"},{\"id\":104,\"answer\":\"Функция, способная работать только с числами типа float\"}]}', '2026-05-15 08:08:59'),
(95, 11, 61, 1, '{\"question_text\":\"Что такое виртуальное окружение (venv)?\",\"answers\":[{\"id\":241,\"answer\":\"Изолированная папка с интерпретатором и библиотеками для конкретного проекта\",\"is_correct\":1},{\"id\":242,\"answer\":\"Облачное хранилище для исходного кода на серверах GitHub\",\"is_correct\":0},{\"id\":243,\"answer\":\"Специальный режим Windows для запуска Linux-приложений\",\"is_correct\":0},{\"id\":244,\"answer\":\"Программа для удаленного управления рабочим столом другого программиста\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(96, 11, 10, 2, '{\"question_text\":\"Что такое диапазон (range)?\",\"answers\":[{\"id\":37,\"answer\":\"Неизменяемая последовательность чисел, которая вычисляется лениво\",\"is_correct\":1},{\"id\":38,\"answer\":\"Список, который хранит абсолютно все числа от старта до финиша\",\"is_correct\":0},{\"id\":39,\"answer\":\"Функция для генерации случайных чисел в заданном промежутке\",\"is_correct\":0},{\"id\":40,\"answer\":\"Метод для автоматического расширения размера списка\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(97, 11, 5, 3, '{\"question_text\":\"Что такое последовательность (Sequence)?\",\"answers\":[{\"id\":17,\"answer\":\"Итерабельный объект, поддерживающий доступ по индексу и знающий свою длину\",\"is_correct\":1},{\"id\":18,\"answer\":\"Любой объект, который был создан внутри цикла for\",\"is_correct\":0},{\"id\":19,\"answer\":\"Функция, которая вызывает саму себя бесконечное количество раз\",\"is_correct\":0},{\"id\":20,\"answer\":\"Список, содержащий только элементы одного и того же типа\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(98, 11, 23, 4, '{\"question_text\":\"Где быстрее поиск: в списке или в словаре?\",\"answers\":[{\"id\":89,\"answer\":\"В словаре поиск O(1), в списке O(n), поэтому словарь быстрее\",\"is_correct\":1},{\"id\":90,\"answer\":\"В списке, так как это упорядоченная последовательность\",\"is_correct\":0},{\"id\":91,\"answer\":\"Скорость одинаковая, так как оба объекта хранятся в куче\",\"is_correct\":0},{\"id\":92,\"answer\":\"В списке, если он отсортирован по возрастанию\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(99, 11, 14, 5, '{\"question_text\":\"Чем список (list) отличается от кортежа (tuple)?\",\"answers\":[{\"id\":53,\"answer\":\"Списки изменяемы (mutable), кортежи — нет (immutable)\",\"is_correct\":1},{\"id\":54,\"answer\":\"В списках можно хранить только числа, а в кортежах — что угодно\",\"is_correct\":0},{\"id\":55,\"answer\":\"Списки работают быстрее кортежей в 10 раз\",\"is_correct\":0},{\"id\":56,\"answer\":\"Кортежи нельзя передавать в качестве аргументов функций\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(100, 11, 47, 6, '{\"question_text\":\"Можно ли извлечь элемент генератора по индексу?\",\"answers\":[{\"id\":185,\"answer\":\"Нет, генераторы поддерживают только последовательный перебор\",\"is_correct\":1},{\"id\":186,\"answer\":\"Да, если генератор содержит только числа типа int\",\"is_correct\":0},{\"id\":187,\"answer\":\"Да, с помощью встроенного метода .get_item()\",\"is_correct\":0},{\"id\":188,\"answer\":\"Только если генератор был создан через списковое включение\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(101, 11, 7, 7, '{\"question_text\":\"Можно ли изменить символ в строке по индексу?\",\"answers\":[{\"id\":25,\"answer\":\"Нет, строки в Python являются неизменяемыми (immutable)\",\"is_correct\":1},{\"id\":26,\"answer\":\"Да, если использовать двойные кавычки вместо одинарных\",\"is_correct\":0},{\"id\":27,\"answer\":\"Да, с помощью метода .replace_at(index, char)\",\"is_correct\":0},{\"id\":28,\"answer\":\"Только если строка содержит только латинские символы\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(102, 11, 6, 8, '{\"question_text\":\"Какие виды строк есть в Python 3?\",\"answers\":[{\"id\":21,\"answer\":\"Только тип str (Юникод), для байтов используется тип bytes\",\"is_correct\":1},{\"id\":22,\"answer\":\"Два типа: str для обычного текста и unicode для спецсимволов\",\"is_correct\":0},{\"id\":23,\"answer\":\"Только ASCII строки, Юникод поддерживается только через библиотеки\",\"is_correct\":0},{\"id\":24,\"answer\":\"Строки делятся на изменяемые и неизменяемые в зависимости от кавычек\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(103, 11, 8, 9, '{\"question_text\":\"Как эффективно соединить список строк в одну?\",\"answers\":[{\"id\":29,\"answer\":\"Использовать строковый метод \\\"\\\".join(list)\",\"is_correct\":1},{\"id\":30,\"answer\":\"Складывать их в цикле с помощью оператора \\\"+\\\"\",\"is_correct\":0},{\"id\":31,\"answer\":\"Воспользоваться встроенной функцией sum(list)\",\"is_correct\":0},{\"id\":32,\"answer\":\"С помощью метода .merge() у объекта списка\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(104, 11, 18, 10, '{\"question_text\":\"Что такое множество (set)?\",\"answers\":[{\"id\":69,\"answer\":\"Неупорядоченная коллекция уникальных хешируемых объектов\",\"is_correct\":1},{\"id\":70,\"answer\":\"Список, который автоматически сортируется при добавлении элемента\",\"is_correct\":0},{\"id\":71,\"answer\":\"Словарь, в котором ключи всегда являются строками\",\"is_correct\":0},{\"id\":72,\"answer\":\"Массив фиксированной длины для хранения целых чисел\",\"is_correct\":0}]}', '2026-05-15 08:22:14'),
(105, 12, 62, 1, '{\"question_text\":\"Принцип KISS?\",\"answers\":[{\"id\":245,\"answer\":\"Keep It Simple, Stupid — призыв к максимальной простоте кода\",\"is_correct\":1},{\"id\":246,\"answer\":\"Keep It Secure, Seriously — приоритет безопасности над скоростью\",\"is_correct\":0},{\"id\":247,\"answer\":\"Класс Интеграции Системных Скриптов — стандарт именования файлов\",\"is_correct\":0},{\"id\":248,\"answer\":\"Метод автоматического объединения конфликтующих веток в Git\",\"is_correct\":0}]}', '2026-05-15 08:48:15'),
(106, 12, 41, 2, '{\"question_text\":\"Что такое итерабельный объект (Iterable)?\",\"answers\":[{\"id\":161,\"answer\":\"Объект, способный возвращать элементы по одному (имеет __iter__ или __getitem__)\",\"is_correct\":1},{\"id\":162,\"answer\":\"Любая переменная, которая была использована внутри цикла while\",\"is_correct\":0},{\"id\":163,\"answer\":\"Функция, которая возвращает результат с помощью ключевого слова return\",\"is_correct\":0},{\"id\":164,\"answer\":\"Объект, который можно вывести в консоль через функцию print()\",\"is_correct\":0}]}', '2026-05-15 08:48:15'),
(107, 12, 15, 3, '{\"question_text\":\"Как сделать список уникальным с сохранением порядка?\",\"answers\":[{\"id\":57,\"answer\":\"Использовать list(dict.fromkeys(my_list))\",\"is_correct\":1},{\"id\":58,\"answer\":\"Преобразовать его в множество set(my_list)\",\"is_correct\":0},{\"id\":59,\"answer\":\"Просто отсортировать список методом .sort()\",\"is_correct\":0},{\"id\":60,\"answer\":\"Использовать функцию unique(my_list)\",\"is_correct\":0}]}', '2026-05-15 08:48:15'),
(108, 12, 46, 4, '{\"question_text\":\"Что такое контекстный менеджер?\",\"answers\":[{\"id\":181,\"answer\":\"Объект с методами __enter__ и __exit__ для автоматического управления ресурсами\",\"is_correct\":1},{\"id\":182,\"answer\":\"Функция, которая управляет глобальными переменными во всем проекте\",\"is_correct\":0},{\"id\":183,\"answer\":\"Инструмент для визуального оформления интерфейса приложения\",\"is_correct\":0},{\"id\":184,\"answer\":\"Тип декоратора, который используется только для классов\",\"is_correct\":0}]}', '2026-05-15 08:48:15'),
(109, 12, 69, 5, '{\"question_text\":\"Что такое Smoke Test?\",\"answers\":[{\"id\":273,\"answer\":\"Базовый набор тестов для проверки работоспособности основных функций\",\"is_correct\":1},{\"id\":274,\"answer\":\"Тестирование приложения до тех пор, пока сервер не начнет \\\"дымиться\\\"\",\"is_correct\":0},{\"id\":275,\"answer\":\"Специальный тест для поиска скрытого (закомментированного) кода\",\"is_correct\":0},{\"id\":276,\"answer\":\"Проверка уровня защиты сетевого экрана (Firewall) от атак\",\"is_correct\":0}]}', '2026-05-15 08:48:15'),
(110, 12, 2, 6, '{\"question_text\":\"Что такое декоратор в Python?\",\"answers\":[{\"id\":5,\"answer\":\"Функция, которая расширяет возможности другой функции, не меняя её исходный код\",\"is_correct\":1},{\"id\":6,\"answer\":\"Специальный тип переменной для хранения настроек стиля кода\",\"is_correct\":0},{\"id\":7,\"answer\":\"Класс, который автоматически удаляет неиспользуемые объекты из памяти\",\"is_correct\":0},{\"id\":8,\"answer\":\"Инструмент для визуального оформления консольного вывода\",\"is_correct\":0}]}', '2026-05-15 08:48:15'),
(111, 12, 64, 7, '{\"question_text\":\"Принцип YAGNI?\",\"answers\":[{\"id\":253,\"answer\":\"You Ain\'t Gonna Need It — отказ от реализации функций \\\"на будущее\\\"\",\"is_correct\":1},{\"id\":254,\"answer\":\"Yield All Global Nested Instances — метод работы с вложенными классами\",\"is_correct\":0},{\"id\":255,\"answer\":\"Yet Another Great Node Interface — стандарт для backend-разработки\",\"is_correct\":0},{\"id\":256,\"answer\":\"Правило обязательного использования глобальных переменных в циклах\",\"is_correct\":0}]}', '2026-05-15 08:48:16'),
(112, 12, 13, 8, '{\"question_text\":\"Как проверить файл .py на ошибки без запуска?\",\"answers\":[{\"id\":49,\"answer\":\"Использовать утилиту py_compile: python -m py_compile file.py\",\"is_correct\":1},{\"id\":50,\"answer\":\"Просто переименовать файл в .txt и прочитать его\",\"is_correct\":0},{\"id\":51,\"answer\":\"Такой возможности нет, ошибки видны только при выполнении\",\"is_correct\":0},{\"id\":52,\"answer\":\"С помощью встроенной функции check_syntax(file_path)\",\"is_correct\":0}]}', '2026-05-15 08:48:16'),
(113, 12, 12, 9, '{\"question_text\":\"Чем отличаются globals() и locals()?\",\"answers\":[{\"id\":45,\"answer\":\"globals() — словарь переменных модуля, locals() — текущей области (функции)\",\"is_correct\":1},{\"id\":46,\"answer\":\"globals() — переменные системы Windows, locals() — только приложения\",\"is_correct\":0},{\"id\":47,\"answer\":\"globals() возвращает список, а locals() всегда возвращает кортеж\",\"is_correct\":0},{\"id\":48,\"answer\":\"Ничем не отличаются, это псевдонимы одной и той же функции\",\"is_correct\":0}]}', '2026-05-15 08:48:16'),
(114, 12, 42, 10, '{\"question_text\":\"Что такое итератор?\",\"answers\":[{\"id\":165,\"answer\":\"Объект, представляющий поток данных и реализующий метод __next__\",\"is_correct\":1},{\"id\":166,\"answer\":\"Встроенный тип данных для хранения координат в двумерном массиве\",\"is_correct\":0},{\"id\":167,\"answer\":\"Переменная-счетчик, которая увеличивается на 1 при каждой итерации цикла\",\"is_correct\":0},{\"id\":168,\"answer\":\"Специальный синтаксис для объединения двух списков в один\",\"is_correct\":0}]}', '2026-05-15 08:48:16'),
(115, 13, 513, 1, '{\"question_text\":\"Что такое первичный ключ (Composite Key)?\",\"answers\":[{\"id\":1639,\"answer\":\"Комбинация из нескольких столбцов, уникально идентифицирующая строку\",\"is_correct\":1},{\"id\":1640,\"answer\":\"Ключ, который автоматически создается из изображения (логотипа)\",\"is_correct\":0},{\"id\":1641,\"answer\":\"Специальный пароль для доступа к базе данных через интернет\",\"is_correct\":0},{\"id\":1642,\"answer\":\"Метод сжатия данных в таблице для экономии места на диске\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(116, 13, 515, 2, '{\"question_text\":\"Что такое CROSS JOIN?\",\"answers\":[{\"id\":1647,\"answer\":\"Декартово произведение: каждая строка первой таблицы с каждой строкой второй\",\"is_correct\":1},{\"id\":1648,\"answer\":\"Метод для входа в базу данных под чужим именем (взлом)\",\"is_correct\":0},{\"id\":1649,\"answer\":\"Тип соединения, который автоматически удаляет все дубликаты\",\"is_correct\":0},{\"id\":1650,\"answer\":\"Команда для объединения таблиц из разных баз данных\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(117, 13, 510, 3, '{\"question_text\":\"В чем разница между UNION и UNION ALL?\",\"answers\":[{\"id\":1627,\"answer\":\"UNION удаляет дубликаты, UNION ALL просто склеивает всё и работает быстрее\",\"is_correct\":1},{\"id\":1628,\"answer\":\"UNION ALL используется только в Linux, а UNION везде\",\"is_correct\":0},{\"id\":1629,\"answer\":\"UNION ALL удаляет данные из первой таблицы, а UNION из второй\",\"is_correct\":0},{\"id\":1630,\"answer\":\"Разницы нет, это два способа написания одного и того же действия\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(118, 13, 486, 4, '{\"question_text\":\"Разница между DELETE и TRUNCATE?\",\"answers\":[{\"id\":1531,\"answer\":\"DELETE удаляет строки по одной, TRUNCATE очищает таблицу целиком\",\"is_correct\":1},{\"id\":1532,\"answer\":\"TRUNCATE используется только для удаления картинок из базы\",\"is_correct\":0},{\"id\":1533,\"answer\":\"DELETE — это платная команда, а TRUNCATE — бесплатная\",\"is_correct\":0},{\"id\":1534,\"answer\":\"После выполнения DELETE база данных SQL удаляется навсегда\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(119, 13, 494, 5, '{\"question_text\":\"Разница между WHERE и HAVING?\",\"answers\":[{\"id\":1563,\"answer\":\"WHERE фильтрует до группировки, HAVING — после\",\"is_correct\":1},{\"id\":1564,\"answer\":\"HAVING используется только для картинок, а WHERE для текста\",\"is_correct\":0},{\"id\":1565,\"answer\":\"WHERE работает в 10 раз быстрее, чем HAVING\",\"is_correct\":0},{\"id\":1566,\"answer\":\"Это два названия одного и того же фильтра\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(120, 13, 511, 6, '{\"question_text\":\"Что такое оператор CASE?\",\"answers\":[{\"id\":1631,\"answer\":\"Аналог if-else: позволяет выводить разные значения в зависимости от условий\",\"is_correct\":1},{\"id\":1632,\"answer\":\"Команда для перевода всех букв в запросе в верхний регистр\",\"is_correct\":0},{\"id\":1633,\"answer\":\"Специальный метод для шифрования имен таблиц в базе данных\",\"is_correct\":0},{\"id\":1634,\"answer\":\"Инструмент для автоматической сортировки папок в проекте\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(121, 13, 493, 7, '{\"question_text\":\"Как реализовать связь \\\"Многие-ко-многим\\\"?\",\"answers\":[{\"id\":1559,\"answer\":\"Через третью промежуточную таблицу с внешними ключами\",\"is_correct\":1},{\"id\":1560,\"answer\":\"Путем записи всех данных в одну огромную ячейку через запятую\",\"is_correct\":0},{\"id\":1561,\"answer\":\"Такая связь невозможна в реляционных базах данных\",\"is_correct\":0},{\"id\":1562,\"answer\":\"Через создание 100 копий одной и той же таблицы\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(122, 13, 490, 8, '{\"question_text\":\"Что такое Внешний ключ (Foreign Key)?\",\"answers\":[{\"id\":1547,\"answer\":\"Поле, которое ссылается на первичный ключ в другой таблице\",\"is_correct\":1},{\"id\":1548,\"answer\":\"Ключ от квартиры, где деньги лежат (в формате SQL)\",\"is_correct\":0},{\"id\":1549,\"answer\":\"Запасной пароль администратора базы данных\",\"is_correct\":0},{\"id\":1550,\"answer\":\"Специальный код для подключения внешних CSS-стилей\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(123, 13, 508, 9, '{\"question_text\":\"Что такое Нормализация?\",\"answers\":[{\"id\":1619,\"answer\":\"Организация данных для исключения дублирования и обеспечения целостности\",\"is_correct\":1},{\"id\":1620,\"answer\":\"Процесс удаления всех запятых и точек из текстовых полей\",\"is_correct\":0},{\"id\":1621,\"answer\":\"Метод автоматического выравнивания текста по центру ячеек\",\"is_correct\":0},{\"id\":1622,\"answer\":\"Настройка базы данных для работы только в дневное время\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(124, 13, 488, 10, '{\"question_text\":\"Разница между CHAR и VARCHAR?\",\"answers\":[{\"id\":1539,\"answer\":\"CHAR — фиксированная длина, VARCHAR — переменная длина\",\"is_correct\":1},{\"id\":1540,\"answer\":\"VARCHAR используется только для цифр, а CHAR — для букв\",\"is_correct\":0},{\"id\":1541,\"answer\":\"CHAR работает в 100 раз медленнее, чем VARCHAR\",\"is_correct\":0},{\"id\":1542,\"answer\":\"Это два разных названия для типа данных Binary\",\"is_correct\":0}]}', '2026-05-16 09:56:51'),
(135, 15, 121, 1, '{\"question_text\":\"В чем разница между enum и enum class (scoped enum)?\",\"answers\":[{\"id\":481,\"answer\":\"enum class строго типизирован и требует указания области видимости (Type::Value)\",\"is_correct\":1},{\"id\":482,\"answer\":\"enum class может хранить только дробные числа, а обычный enum только целые\",\"is_correct\":0},{\"id\":483,\"answer\":\"Обычный enum был удален из стандарта C++20 и заменен на enum class\",\"is_correct\":0},{\"id\":484,\"answer\":\"enum class автоматически шифрует свои значения для защиты памяти\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(136, 15, 123, 2, '{\"question_text\":\"Что такое переполнение стека (Stack Overflow)?\",\"answers\":[{\"id\":489,\"answer\":\"Исчерпание памяти стека, обычно вызванное бесконечной рекурсией\",\"is_correct\":1},{\"id\":490,\"answer\":\"Ситуация, когда база данных SQL превышает размер 1 гигабайт\",\"is_correct\":0},{\"id\":491,\"answer\":\"Ошибка, возникающая при одновременном открытии 100 вкладок в браузере\",\"is_correct\":0},{\"id\":492,\"answer\":\"Процесс удаления всех файлов из папки проекта во время компиляции\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(137, 15, 115, 3, '{\"question_text\":\"Что такое лямбда-выражение?\",\"answers\":[{\"id\":457,\"answer\":\"Анонимная функция, которую можно объявить прямо внутри кода\",\"is_correct\":1},{\"id\":458,\"answer\":\"Способ вычисления числа ПИ с точностью до миллиона знаков\",\"is_correct\":0},{\"id\":459,\"answer\":\"Использование греческих символов для именования переменных\",\"is_correct\":0},{\"id\":460,\"answer\":\"Метод принудительного закрытия всех открытых файлов на компьютере\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(138, 15, 160, 4, '{\"question_text\":\"Зачем нужны стандартные дескрипторы 0, 1, 2?\",\"answers\":[{\"id\":637,\"answer\":\"Для стандартного ввода (0), вывода (1) и ошибок (2)\",\"is_correct\":1},{\"id\":638,\"answer\":\"Это координаты окна программы на экране пользователя\",\"is_correct\":0},{\"id\":639,\"answer\":\"Уровни громкости динамиков, подключенных к серверу\",\"is_correct\":0},{\"id\":640,\"answer\":\"Коды цветов в формате RGB для отрисовки интерфейса\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(139, 15, 125, 5, '{\"question_text\":\"Что такое сегментация памяти (Segfault)?\",\"answers\":[{\"id\":497,\"answer\":\"Ошибка при попытке доступа к недоступному или защищенному участку памяти\",\"is_correct\":1},{\"id\":498,\"answer\":\"Процесс разделения жесткого диска на несколько виртуальных разделов\",\"is_correct\":0},{\"id\":499,\"answer\":\"Специальный алгоритм для быстрой отрисовки теней в видеоиграх\",\"is_correct\":0},{\"id\":500,\"answer\":\"Автоматическое исправление опечаток в названиях переменных\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(140, 15, 85, 6, '{\"question_text\":\"Что будет, если вызвать delete у объекта, созданного через new[]?\",\"answers\":[{\"id\":337,\"answer\":\"Неопределенное поведение (Undefined Behavior)\",\"is_correct\":1},{\"id\":338,\"answer\":\"Память корректно освободится, но программа будет ждать 1 секунду\",\"is_correct\":0},{\"id\":339,\"answer\":\"Размер объекта в памяти автоматически увеличится в два раза\",\"is_correct\":0},{\"id\":340,\"answer\":\"Браузер пользователя выдаст ошибку доступа к ресурсу\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(141, 15, 152, 7, '{\"question_text\":\"В чем разница между std::vector::size() и std::vector::capacity()?\",\"answers\":[{\"id\":605,\"answer\":\"size — количество элементов, capacity — размер выделенной памяти\",\"is_correct\":1},{\"id\":606,\"answer\":\"capacity всегда в 10 раз больше, чем size, по требованию стандарта\",\"is_correct\":0},{\"id\":607,\"answer\":\"size измеряется в байтах, а capacity — в битах\",\"is_correct\":0},{\"id\":608,\"answer\":\"Это два разных названия одного и того же значения\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(142, 15, 155, 8, '{\"question_text\":\"Зачем использовать std::reserve()?\",\"answers\":[{\"id\":617,\"answer\":\"Чтобы заранее выделить память и избежать переаллокаций\",\"is_correct\":1},{\"id\":618,\"answer\":\"Чтобы уменьшить размер вектора до минимально возможного\",\"is_correct\":0},{\"id\":619,\"answer\":\"Для автоматического шифрования всех данных внутри вектора\",\"is_correct\":0},{\"id\":620,\"answer\":\"Эта команда отправляет данные вектора на удаленный сервер\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(143, 15, 159, 9, '{\"question_text\":\"Что такое PID в Linux?\",\"answers\":[{\"id\":633,\"answer\":\"Уникальный номер (идентификатор) процесса в системе\",\"is_correct\":1},{\"id\":634,\"answer\":\"Личный идентификационный номер программиста в реестре Linux\",\"is_correct\":0},{\"id\":635,\"answer\":\"Пароль для получения прав суперпользователя (root)\",\"is_correct\":0},{\"id\":636,\"answer\":\"Название драйвера для подключения старых принтеров\",\"is_correct\":0}]}', '2026-05-16 10:04:40'),
(144, 15, 150, 10, '{\"question_text\":\"Что такое делегирующий конструктор?\",\"answers\":[{\"id\":597,\"answer\":\"Возможность одного конструктора вызывать другой конструктор того же класса\",\"is_correct\":1},{\"id\":598,\"answer\":\"Процесс передачи написания кода на аутсорс в другую компанию\",\"is_correct\":0},{\"id\":599,\"answer\":\"Конструктор, который работает только по доверенности от операционной системы\",\"is_correct\":0},{\"id\":600,\"answer\":\"Метод автоматического создания объектов на основе чертежей из AutoCAD\",\"is_correct\":0}]}', '2026-05-16 10:04:41'),
(145, 16, 10, 1, '{\"question_text\":\"Что такое диапазон (range)?\",\"answers\":[{\"id\":37,\"answer\":\"Неизменяемая последовательность чисел, которая вычисляется лениво\",\"is_correct\":1},{\"id\":38,\"answer\":\"Список, который хранит абсолютно все числа от старта до финиша\",\"is_correct\":0},{\"id\":39,\"answer\":\"Функция для генерации случайных чисел в заданном промежутке\",\"is_correct\":0},{\"id\":40,\"answer\":\"Метод для автоматического расширения размера списка\",\"is_correct\":0}]}', '2026-05-16 10:06:45'),
(146, 16, 47, 2, '{\"question_text\":\"Можно ли извлечь элемент генератора по индексу?\",\"answers\":[{\"id\":185,\"answer\":\"Нет, генераторы поддерживают только последовательный перебор\",\"is_correct\":1},{\"id\":186,\"answer\":\"Да, если генератор содержит только числа типа int\",\"is_correct\":0},{\"id\":187,\"answer\":\"Да, с помощью встроенного метода .get_item()\",\"is_correct\":0},{\"id\":188,\"answer\":\"Только если генератор был создан через списковое включение\",\"is_correct\":0}]}', '2026-05-16 10:06:45'),
(147, 16, 23, 3, '{\"question_text\":\"Где быстрее поиск: в списке или в словаре?\",\"answers\":[{\"id\":89,\"answer\":\"В словаре поиск O(1), в списке O(n), поэтому словарь быстрее\",\"is_correct\":1},{\"id\":90,\"answer\":\"В списке, так как это упорядоченная последовательность\",\"is_correct\":0},{\"id\":91,\"answer\":\"Скорость одинаковая, так как оба объекта хранятся в куче\",\"is_correct\":0},{\"id\":92,\"answer\":\"В списке, если он отсортирован по возрастанию\",\"is_correct\":0}]}', '2026-05-16 10:06:45'),
(148, 16, 24, 4, '{\"question_text\":\"В чем разница между *args и **kwargs?\",\"answers\":[{\"id\":93,\"answer\":\"*args — кортеж позиционных аргументов, **kwargs — словарь именованных\",\"is_correct\":1},{\"id\":94,\"answer\":\"*args используется в классах, а **kwargs только в обычных функциях\",\"is_correct\":0},{\"id\":95,\"answer\":\"*args — это список, а **kwargs — это неизменяемый кортеж\",\"is_correct\":0},{\"id\":96,\"answer\":\"Разницы нет, это два названия для одного и того же механизма\",\"is_correct\":0}]}', '2026-05-16 10:06:45'),
(149, 16, 14, 5, '{\"question_text\":\"Чем список (list) отличается от кортежа (tuple)?\",\"answers\":[{\"id\":53,\"answer\":\"Списки изменяемы (mutable), кортежи — нет (immutable)\",\"is_correct\":1},{\"id\":54,\"answer\":\"В списках можно хранить только числа, а в кортежах — что угодно\",\"is_correct\":0},{\"id\":55,\"answer\":\"Списки работают быстрее кортежей в 10 раз\",\"is_correct\":0},{\"id\":56,\"answer\":\"Кортежи нельзя передавать в качестве аргументов функций\",\"is_correct\":0}]}', '2026-05-16 10:06:46'),
(150, 16, 18, 6, '{\"question_text\":\"Что такое множество (set)?\",\"answers\":[{\"id\":69,\"answer\":\"Неупорядоченная коллекция уникальных хешируемых объектов\",\"is_correct\":1},{\"id\":70,\"answer\":\"Список, который автоматически сортируется при добавлении элемента\",\"is_correct\":0},{\"id\":71,\"answer\":\"Словарь, в котором ключи всегда являются строками\",\"is_correct\":0},{\"id\":72,\"answer\":\"Массив фиксированной длины для хранения целых чисел\",\"is_correct\":0}]}', '2026-05-16 10:06:46'),
(151, 16, 5, 7, '{\"question_text\":\"Что такое последовательность (Sequence)?\",\"answers\":[{\"id\":17,\"answer\":\"Итерабельный объект, поддерживающий доступ по индексу и знающий свою длину\",\"is_correct\":1},{\"id\":18,\"answer\":\"Любой объект, который был создан внутри цикла for\",\"is_correct\":0},{\"id\":19,\"answer\":\"Функция, которая вызывает саму себя бесконечное количество раз\",\"is_correct\":0},{\"id\":20,\"answer\":\"Список, содержащий только элементы одного и того же типа\",\"is_correct\":0}]}', '2026-05-16 10:06:46'),
(152, 16, 61, 8, '{\"question_text\":\"Что такое виртуальное окружение (venv)?\",\"answers\":[{\"id\":241,\"answer\":\"Изолированная папка с интерпретатором и библиотеками для конкретного проекта\",\"is_correct\":1},{\"id\":242,\"answer\":\"Облачное хранилище для исходного кода на серверах GitHub\",\"is_correct\":0},{\"id\":243,\"answer\":\"Специальный режим Windows для запуска Linux-приложений\",\"is_correct\":0},{\"id\":244,\"answer\":\"Программа для удаленного управления рабочим столом другого программиста\",\"is_correct\":0}]}', '2026-05-16 10:06:46'),
(153, 16, 6, 9, '{\"question_text\":\"Какие виды строк есть в Python 3?\",\"answers\":[{\"id\":21,\"answer\":\"Только тип str (Юникод), для байтов используется тип bytes\",\"is_correct\":1},{\"id\":22,\"answer\":\"Два типа: str для обычного текста и unicode для спецсимволов\",\"is_correct\":0},{\"id\":23,\"answer\":\"Только ASCII строки, Юникод поддерживается только через библиотеки\",\"is_correct\":0},{\"id\":24,\"answer\":\"Строки делятся на изменяемые и неизменяемые в зависимости от кавычек\",\"is_correct\":0}]}', '2026-05-16 10:06:46'),
(154, 16, 7, 10, '{\"question_text\":\"Можно ли изменить символ в строке по индексу?\",\"answers\":[{\"id\":25,\"answer\":\"Нет, строки в Python являются неизменяемыми (immutable)\",\"is_correct\":1},{\"id\":26,\"answer\":\"Да, если использовать двойные кавычки вместо одинарных\",\"is_correct\":0},{\"id\":27,\"answer\":\"Да, с помощью метода .replace_at(index, char)\",\"is_correct\":0},{\"id\":28,\"answer\":\"Только если строка содержит только латинские символы\",\"is_correct\":0}]}', '2026-05-16 10:06:46'),
(162, 18, 524, 1, '{\"question_text\":\"Разница между Кластерным и Некластерным индексом?\",\"answers\":[{\"id\":1683,\"answer\":\"Кластерный определяет физический порядок строк на диске, некластерный — нет\",\"is_correct\":1},{\"id\":1684,\"answer\":\"Кластерный индекс работает только в облаке, а некластерный — локально\",\"is_correct\":0},{\"id\":1685,\"answer\":\"Некластерный индекс всегда в 100 раз быстрее кластерного\",\"is_correct\":0},{\"id\":1686,\"answer\":\"Это два названия одного и того же алгоритма из стандарта SQL-92\",\"is_correct\":0}]}', '2026-05-16 10:12:56'),
(163, 18, 501, 2, '{\"question_text\":\"Что такое Оконные функции (Window Functions)?\",\"answers\":[{\"id\":1591,\"answer\":\"Функции (OVER), выполняющие вычисления без сворачивания строк в одну группу\",\"is_correct\":1},{\"id\":1592,\"answer\":\"Функции для управления размером окон в операционной системе Windows\",\"is_correct\":0},{\"id\":1593,\"answer\":\"Команды для автоматической очистки кэша браузера через SQL\",\"is_correct\":0},{\"id\":1594,\"answer\":\"Специальные заготовки для создания графического интерфейса баз данных\",\"is_correct\":0}]}', '2026-05-16 10:12:56'),
(164, 18, 504, 3, '{\"question_text\":\"Что такое Уровни изоляции транзакций?\",\"answers\":[{\"id\":1603,\"answer\":\"Настройки видимости изменений одной транзакции для других\",\"is_correct\":1},{\"id\":1604,\"answer\":\"Уровни громкости звуковых уведомлений при ошибках в БД\",\"is_correct\":0},{\"id\":1605,\"answer\":\"Количество копий базы данных, которые хранятся на сервере\",\"is_correct\":0},{\"id\":1606,\"answer\":\"Процесс разделения жесткого диска на логические сектора\",\"is_correct\":0}]}', '2026-05-16 10:12:57'),
(165, 18, 529, 4, '{\"question_text\":\"Что такое B-Tree индекс?\",\"answers\":[{\"id\":1703,\"answer\":\"Сбалансированное дерево — стандартная структура индекса для поиска\",\"is_correct\":1},{\"id\":1704,\"answer\":\"Вторая (B) версия дерева категорий внутри интернет-магазина\",\"is_correct\":0},{\"id\":1705,\"answer\":\"Специальный формат для отрисовки деревьев в 3D графике\",\"is_correct\":0},{\"id\":1706,\"answer\":\"Алгоритм, который работает только на процессорах компании AMD\",\"is_correct\":0}]}', '2026-05-16 10:12:57'),
(166, 18, 509, 5, '{\"question_text\":\"Что такое Триггер?\",\"answers\":[{\"id\":1623,\"answer\":\"Хранимая процедура, автоматически выполняемая при событии (INSERT\\/UPDATE)\",\"is_correct\":1},{\"id\":1624,\"answer\":\"Кнопка \\\"Пуск\\\" внутри интерфейса управления базой данных\",\"is_correct\":0},{\"id\":1625,\"answer\":\"Специальный вирус, который удаляет данные по расписанию\",\"is_correct\":0},{\"id\":1626,\"answer\":\"Метод для связи базы данных SQL с мобильным телефоном\",\"is_correct\":0}]}', '2026-05-16 10:12:57'),
(167, 18, 507, 6, '{\"question_text\":\"Зачем нужен EXPLAIN?\",\"answers\":[{\"id\":1615,\"answer\":\"Команда для просмотра плана выполнения запроса и поиска узких мест\",\"is_correct\":1},{\"id\":1616,\"answer\":\"Метод объяснения пользователю, как пользоваться вашим сайтом\",\"is_correct\":0},{\"id\":1617,\"answer\":\"Функция, которая переводит SQL-код на человеческий язык\",\"is_correct\":0},{\"id\":1618,\"answer\":\"Специальный комментарий, который запрещает компиляцию запроса\",\"is_correct\":0}]}', '2026-05-16 10:12:57'),
(168, 18, 518, 7, '{\"question_text\":\"Что такое Рекурсивный CTE?\",\"answers\":[{\"id\":1659,\"answer\":\"Запрос, который ссылается на самого себя для работы с иерархиями\",\"is_correct\":1},{\"id\":1660,\"answer\":\"Специальный вирус, который бесконечно копирует данные в таблице\",\"is_correct\":0},{\"id\":1661,\"answer\":\"Процесс автоматического удаления старых версий базы данных\",\"is_correct\":0},{\"id\":1662,\"answer\":\"Метод сжатия текстовых полей до минимально возможного размера\",\"is_correct\":0}]}', '2026-05-16 10:12:57'),
(169, 18, 525, 8, '{\"question_text\":\"Что такое Покрывающий индекс (Covering Index)?\",\"answers\":[{\"id\":1687,\"answer\":\"Индекс, содержащий все поля запроса (БД не обращается к таблице)\",\"is_correct\":1},{\"id\":1688,\"answer\":\"Метод автоматического скрытия (покрытия) секретных данных\",\"is_correct\":0},{\"id\":1689,\"answer\":\"Специальный чехол для защиты сервера от влаги и пыли\",\"is_correct\":0},{\"id\":1690,\"answer\":\"Тип данных для хранения информации о покрытии сотовой связи\",\"is_correct\":0}]}', '2026-05-16 10:12:57'),
(170, 18, 526, 9, '{\"question_text\":\"Что такое Селективность индекса?\",\"answers\":[{\"id\":1691,\"answer\":\"Мера уникальности значений: чем выше, тем эффективнее работает индекс\",\"is_correct\":1},{\"id\":1692,\"answer\":\"Способность базы данных выбирать только красивые картинки\",\"is_correct\":0},{\"id\":1693,\"answer\":\"Настройка монитора для улучшения цветопередачи в IDE\",\"is_correct\":0},{\"id\":1694,\"answer\":\"Ограничение на количество одновременных запросов к таблице\",\"is_correct\":0}]}', '2026-05-16 10:12:57'),
(171, 18, 522, 10, '{\"question_text\":\"Как работает Deadlock в БД?\",\"answers\":[{\"id\":1675,\"answer\":\"Взаимная блокировка двух транзакций, ожидающих ресурсы друг друга\",\"is_correct\":1},{\"id\":1676,\"answer\":\"Полное отключение питания сервера при обнаружении ошибки\",\"is_correct\":0},{\"id\":1677,\"answer\":\"Сценарий, при котором все пароли в базе заменяются на случайные\",\"is_correct\":0},{\"id\":1678,\"answer\":\"Метод автоматической блокировки спам-сообщений в чате\",\"is_correct\":0}]}', '2026-05-16 10:12:57'),
(172, 19, 167, 1, '{\"question_text\":\"Что такое \\\"Static Initialization Order Fiasco\\\"?\",\"answers\":[{\"id\":665,\"answer\":\"Проблема неопределенного порядка инициализации статических объектов\",\"is_correct\":1},{\"id\":666,\"answer\":\"Ситуация, когда статические переменные занимают всё место на диске\",\"is_correct\":0},{\"id\":667,\"answer\":\"Ошибка при попытке объявить более 10 статических методов в классе\",\"is_correct\":0},{\"id\":668,\"answer\":\"Метод автоматического удаления дубликатов статического кода\",\"is_correct\":0}]}', '2026-05-16 10:13:14'),
(173, 19, 137, 2, '{\"question_text\":\"Что такое барьеры памяти (Memory Barriers)?\",\"answers\":[{\"id\":545,\"answer\":\"Инструкции процессора, гарантирующие строгий порядок операций с памятью\",\"is_correct\":1},{\"id\":546,\"answer\":\"Физические перегородки внутри системного блока для охлаждения планок RAM\",\"is_correct\":0},{\"id\":547,\"answer\":\"Специальный вид антивируса, который запрещает программам читать чужие данные\",\"is_correct\":0},{\"id\":548,\"answer\":\"Состояние, при котором программа не может выделить больше 1 мегабайта памяти\",\"is_correct\":0}]}', '2026-05-16 10:13:14'),
(174, 19, 163, 3, '{\"question_text\":\"Что такое корутины (Coroutines) в C++20?\",\"answers\":[{\"id\":649,\"answer\":\"Функции, способные приостанавливать и возобновлять свое выполнение\",\"is_correct\":1},{\"id\":650,\"answer\":\"Функции, которые выполняются прямо внутри BIOS материнской платы\",\"is_correct\":0},{\"id\":651,\"answer\":\"Команды для управления роботами через порт USB\",\"is_correct\":0},{\"id\":652,\"answer\":\"Зашифрованные функции, которые нельзя взломать через интернет\",\"is_correct\":0}]}', '2026-05-16 10:13:14'),
(175, 19, 139, 4, '{\"question_text\":\"Что такое lock-free алгоритмы?\",\"answers\":[{\"id\":553,\"answer\":\"Алгоритмы без использования мьютексов, гарантирующие прогресс хотя бы одного потока\",\"is_correct\":1},{\"id\":554,\"answer\":\"Бесплатные алгоритмы, за использование которых не нужно платить лицензионные сборы\",\"is_correct\":0},{\"id\":555,\"answer\":\"Программы, которые работают даже если компьютер полностью заблокирован паролем\",\"is_correct\":0},{\"id\":556,\"answer\":\"Метод автоматического удаления всех замков (locks) из исходного кода проекта\",\"is_correct\":0}]}', '2026-05-16 10:13:14'),
(176, 19, 133, 5, '{\"question_text\":\"Что такое шаблоны вариативных аргументов (Variadic Templates)?\",\"answers\":[{\"id\":529,\"answer\":\"Шаблоны, способные принимать любое количество аргументов разных типов\",\"is_correct\":1},{\"id\":530,\"answer\":\"Специальные заготовки для создания графических интерфейсов сайтов\",\"is_correct\":0},{\"id\":531,\"answer\":\"Функции, которые всегда возвращают случайный результат при вызове\",\"is_correct\":0},{\"id\":532,\"answer\":\"Тип данных для хранения очень длинных математических формул\",\"is_correct\":0}]}', '2026-05-16 10:13:14'),
(177, 19, 102, 6, '{\"question_text\":\"Что такое SFINAE?\",\"answers\":[{\"id\":405,\"answer\":\"Substitution Failure Is Not An Error: ошибка подстановки в шаблон — не ошибка\",\"is_correct\":1},{\"id\":406,\"answer\":\"Super Fast Internal Network Engine: движок для работы с сетями\",\"is_correct\":0},{\"id\":407,\"answer\":\"Состояние, при котором процессор перегревается из-за сложных вычислений\",\"is_correct\":0},{\"id\":408,\"answer\":\"Специальный формат сжатия кода для уменьшения размера exe-файла\",\"is_correct\":0}]}', '2026-05-16 10:13:14'),
(178, 19, 144, 7, '{\"question_text\":\"Что такое концепты (Concepts) в C++20?\",\"answers\":[{\"id\":573,\"answer\":\"Средство наложения ограничений на типы в шаблонах на этапе компиляции\",\"is_correct\":1},{\"id\":574,\"answer\":\"Наброски дизайна интерфейса, сделанные ведущим программистом в Figma\",\"is_correct\":0},{\"id\":575,\"answer\":\"Список всех функций, которые планируется добавить в стандарт C++26\",\"is_correct\":0},{\"id\":576,\"answer\":\"Искусственный интеллект, встроенный в компилятор для поиска багов\",\"is_correct\":0}]}', '2026-05-16 10:13:14'),
(179, 19, 164, 8, '{\"question_text\":\"Что такое концепты (Concepts)?\",\"answers\":[{\"id\":653,\"answer\":\"Ограничения параметров шаблонов на этапе компиляции\",\"is_correct\":1},{\"id\":654,\"answer\":\"Чертежи дизайна интерфейса, сделанные программистом\",\"is_correct\":0},{\"id\":655,\"answer\":\"Новые языки программирования, которые появятся после C++\",\"is_correct\":0},{\"id\":656,\"answer\":\"Список всех функций, которые будут удалены из стандарта C++30\",\"is_correct\":0}]}', '2026-05-16 10:13:15'),
(180, 19, 130, 9, '{\"question_text\":\"Для чего нужно приватное наследование?\",\"answers\":[{\"id\":517,\"answer\":\"Для реализации отношения \\\"реализовано с помощью чего-то\\\" (has-a)\",\"is_correct\":1},{\"id\":518,\"answer\":\"Чтобы скрыть факт того, что у класса вообще есть родители\",\"is_correct\":0},{\"id\":519,\"answer\":\"Для создания классов, которые работают только внутри анонимных сетей\",\"is_correct\":0},{\"id\":520,\"answer\":\"Оно используется только при разработке драйверов для Windows\",\"is_correct\":0}]}', '2026-05-16 10:13:15'),
(181, 19, 91, 10, '{\"question_text\":\"Что такое Placement new?\",\"answers\":[{\"id\":361,\"answer\":\"Оператор, позволяющий создать объект в заранее выделенной области памяти\",\"is_correct\":1},{\"id\":362,\"answer\":\"Метод автоматического размещения окон приложения на экране\",\"is_correct\":0},{\"id\":363,\"answer\":\"Специальный тип указателя, который нельзя удалять через delete\",\"is_correct\":0},{\"id\":364,\"answer\":\"Команда для перемещения объекта из кучи в стек во время выполнения\",\"is_correct\":0}]}', '2026-05-16 10:13:15'),
(243, 27, 301, 1, '{\"question_text\":\"Что такое Image Map?\",\"answers\":[{\"id\":1191,\"answer\":\"Тег <map> для создания нескольких кликабельных зон на одной картинке\",\"is_correct\":1},{\"id\":1192,\"answer\":\"Карта всех серверов, на которых хранятся изображения вашего сайта\",\"is_correct\":0},{\"id\":1193,\"answer\":\"Специальный формат изображений со встроенной GPS-навигацией\",\"is_correct\":0},{\"id\":1194,\"answer\":\"Метод автоматической группировки всех картинок в одну папку\",\"is_correct\":0}]}', '2026-05-16 10:36:47'),
(244, 27, 327, 2, '{\"question_text\":\"Разница между тегами <progress> и <meter>?\",\"answers\":[{\"id\":1295,\"answer\":\"progress для хода выполнения, meter для статических измерений\",\"is_correct\":1},{\"id\":1296,\"answer\":\"meter используется только в играх, а progress в бэкенде\",\"is_correct\":0},{\"id\":1297,\"answer\":\"progress работает медленнее, так как требует JS\",\"is_correct\":0},{\"id\":1298,\"answer\":\"Разницы нет, это два названия одного и того же индикатора\",\"is_correct\":0}]}', '2026-05-16 10:36:47'),
(245, 27, 332, 3, '{\"question_text\":\"Что такое \\\"Схлопывание границ\\\" в контексте чистого HTML?\",\"answers\":[{\"id\":1315,\"answer\":\"Объединение вертикальных отступов соседних блоков в один\",\"is_correct\":1},{\"id\":1316,\"answer\":\"Ошибка, при которой текст вылазит за пределы экрана\",\"is_correct\":0},{\"id\":1317,\"answer\":\"Процесс удаления всех рамок (borders) у таблиц\",\"is_correct\":0},{\"id\":1318,\"answer\":\"Метод автоматического уменьшения размера шрифта\",\"is_correct\":0}]}', '2026-05-16 10:36:47');
INSERT INTO `interview_questions` (`id`, `interview_id`, `question_id`, `question_order`, `question_snapshot`, `created_at`) VALUES
(246, 27, 308, 4, '{\"question_text\":\"Сколько тегов <main> может быть на странице?\",\"answers\":[{\"id\":1219,\"answer\":\"Только один\",\"is_correct\":1},{\"id\":1220,\"answer\":\"Не более десяти\",\"is_correct\":0},{\"id\":1221,\"answer\":\"Ровно три: в начале, в середине и в конце\",\"is_correct\":0},{\"id\":1222,\"answer\":\"Любое количество, это не ограничено правилами\",\"is_correct\":0}]}', '2026-05-16 10:36:47'),
(247, 27, 333, 5, '{\"question_text\":\"Что такое атрибуты async и defer для тега <script>?\",\"answers\":[{\"id\":1319,\"answer\":\"async — выполнение сразу, defer — после парсинга всего HTML\",\"is_correct\":1},{\"id\":1320,\"answer\":\"defer работает только в Internet Explorer 6, async — везде\",\"is_correct\":0},{\"id\":1321,\"answer\":\"Эти атрибуты нужны для подключения стилей CSS, а не скриптов\",\"is_correct\":0},{\"id\":1322,\"answer\":\"async делает код платным, а defer оставляет его бесплатным\",\"is_correct\":0}]}', '2026-05-16 10:36:47'),
(248, 27, 313, 6, '{\"question_text\":\"Что такое элемент <canvas>?\",\"answers\":[{\"id\":1239,\"answer\":\"Область для рисования 2D\\/3D графики с помощью JavaScript\",\"is_correct\":1},{\"id\":1240,\"answer\":\"Специальный фильтр для автоматической обработки фотографий\",\"is_correct\":0},{\"id\":1241,\"answer\":\"Тип контейнера, который может хранить только файлы формата .psd\",\"is_correct\":0},{\"id\":1242,\"answer\":\"Инструмент для создания таблиц с неограниченным числом строк\",\"is_correct\":0}]}', '2026-05-16 10:36:47'),
(249, 27, 329, 7, '{\"question_text\":\"Что такое ARIA-роли (role=\\\"...\\\")?\",\"answers\":[{\"id\":1303,\"answer\":\"Атрибуты для улучшения доступности сайта (скринридеры)\",\"is_correct\":1},{\"id\":1304,\"answer\":\"Список всех ролей сотрудников внутри компании-разработчика\",\"is_correct\":0},{\"id\":1305,\"answer\":\"Специальный метод для настройки анимаций через HTML\",\"is_correct\":0},{\"id\":1306,\"answer\":\"Протокол для передачи аудио и видео данных в реальном времени\",\"is_correct\":0}]}', '2026-05-16 10:36:47'),
(267, 30, 323, 1, '{\"question_text\":\"Зачем нужен тег <figure> и <figcaption>?\",\"answers\":[{\"id\":1279,\"answer\":\"Для группировки контента (картинка, код) и добавления подписи\",\"is_correct\":1},{\"id\":1280,\"answer\":\"Для создания трехмерных моделей внутри браузера\",\"is_correct\":0},{\"id\":1281,\"answer\":\"Специальный формат для хранения зашифрованных паролей\",\"is_correct\":0},{\"id\":1282,\"answer\":\"Метод принудительной очистки кэша изображений\",\"is_correct\":0}]}', '2026-05-16 10:42:40'),
(268, 30, 310, 2, '{\"question_text\":\"Что такое метатеги?\",\"answers\":[{\"id\":1227,\"answer\":\"Теги в <head> для описания данных о странице (charset, description)\",\"is_correct\":1},{\"id\":1228,\"answer\":\"Кнопки в футере сайта для перехода в социальные сети\",\"is_correct\":0},{\"id\":1229,\"answer\":\"Специальные теги для майнинга криптовалюты в браузере\",\"is_correct\":0},{\"id\":1230,\"answer\":\"Зашифрованные команды для связи сервера с базой данных\",\"is_correct\":0}]}', '2026-05-16 10:42:40'),
(269, 30, 326, 3, '{\"question_text\":\"Что такое тег <datalist>?\",\"answers\":[{\"id\":1291,\"answer\":\"Список вариантов для автодополнения (autocomplete) в инпуте\",\"is_correct\":1},{\"id\":1292,\"answer\":\"База данных, которая хранится прямо внутри HTML-файла\",\"is_correct\":0},{\"id\":1293,\"answer\":\"Список всех файлов, которые загрузил пользователь на сайт\",\"is_correct\":0},{\"id\":1294,\"answer\":\"Специальный тип массива для JavaScript-объектов\",\"is_correct\":0}]}', '2026-05-16 10:42:41'),
(270, 30, 305, 4, '{\"question_text\":\"Зачем нужен тег <label> и атрибут for?\",\"answers\":[{\"id\":1207,\"answer\":\"Для связи текста с полем ввода и улучшения доступности\",\"is_correct\":1},{\"id\":1208,\"answer\":\"Чтобы добавить красивую рамку вокруг поля ввода через HTML\",\"is_correct\":0},{\"id\":1209,\"answer\":\"Этот тег нужен только для вставки логотипа компании в форму\",\"is_correct\":0},{\"id\":1210,\"answer\":\"Для защиты формы от спам-ботов без использования капчи\",\"is_correct\":0}]}', '2026-05-16 10:42:41'),
(271, 30, 319, 5, '{\"question_text\":\"Разница между тегами <button> и <input type=\\\"button\\\">?\",\"answers\":[{\"id\":1263,\"answer\":\"<button> может содержать вложенные теги (текст + иконка)\",\"is_correct\":1},{\"id\":1264,\"answer\":\"<input type=\\\"button\\\"> работает только на мобильных устройствах\",\"is_correct\":0},{\"id\":1265,\"answer\":\"<button> — это платный тег, а <input> — бесплатный\",\"is_correct\":0},{\"id\":1266,\"answer\":\"Разницы нет, это два названия одного и того же элемента\",\"is_correct\":0}]}', '2026-05-16 10:42:41'),
(272, 30, 309, 6, '{\"question_text\":\"Зачем нужны теги <section> и <article>?\",\"answers\":[{\"id\":1223,\"answer\":\"section для групп контента, article для независимых цельных блоков\",\"is_correct\":1},{\"id\":1224,\"answer\":\"article используется только для газетных статей в интернете\",\"is_correct\":0},{\"id\":1225,\"answer\":\"section ускоряет загрузку страницы, а article замедляет её\",\"is_correct\":0},{\"id\":1226,\"answer\":\"Это устаревшие теги, которые заменили на <div> в HTML5\",\"is_correct\":0}]}', '2026-05-16 10:42:41'),
(273, 30, 335, 7, '{\"question_text\":\"Зачем нужен тег <noscript>?\",\"answers\":[{\"id\":1327,\"answer\":\"Для вывода контента, если в браузере отключен JavaScript\",\"is_correct\":1},{\"id\":1328,\"answer\":\"Запрещает пользователю писать любые скрипты на странице\",\"is_correct\":0},{\"id\":1329,\"answer\":\"Специальный тег для вставки кода на языке C++\",\"is_correct\":0},{\"id\":1330,\"answer\":\"Метод для полной блокировки клавиатуры пользователя\",\"is_correct\":0}]}', '2026-05-16 10:42:41'),
(274, 30, 306, 8, '{\"question_text\":\"Что такое семантическая верстка?\",\"answers\":[{\"id\":1211,\"answer\":\"Использование тегов согласно их смыслу (header, main, section)\",\"is_correct\":1},{\"id\":1212,\"answer\":\"Верстка сайта только с помощью тегов <div> и <span>\",\"is_correct\":0},{\"id\":1213,\"answer\":\"Автоматический перевод сайта на 100 языков через нейросеть\",\"is_correct\":0},{\"id\":1214,\"answer\":\"Процесс удаления всех CSS-стилей из готового проекта\",\"is_correct\":0}]}', '2026-05-16 10:42:41'),
(275, 30, 312, 9, '{\"question_text\":\"Что делает <meta name=\\\"viewport\\\">?\",\"answers\":[{\"id\":1235,\"answer\":\"Управляет масштабированием и отображением на мобильных устройствах\",\"is_correct\":1},{\"id\":1236,\"answer\":\"Делает скриншот экрана пользователя при входе на сайт\",\"is_correct\":0},{\"id\":1237,\"answer\":\"Позволяет пользователю смотреть видео через VR-очки\",\"is_correct\":0},{\"id\":1238,\"answer\":\"Эта команда удаляет все картинки со страницы для экономии трафика\",\"is_correct\":0}]}', '2026-05-16 10:42:41'),
(276, 30, 321, 10, '{\"question_text\":\"Разница между тегами <ul>, <ol> и <dl>?\",\"answers\":[{\"id\":1271,\"answer\":\"ul — маркеры, ol — числа, dl — список определений\",\"is_correct\":1},{\"id\":1272,\"answer\":\"ul — для картинок, ol — для ссылок, dl — для текста\",\"is_correct\":0},{\"id\":1273,\"answer\":\"ol всегда работает в 10 раз быстрее, чем ul\",\"is_correct\":0},{\"id\":1274,\"answer\":\"DL — это старый формат, который запрещен в HTML5\",\"is_correct\":0}]}', '2026-05-16 10:42:41'),
(277, 31, 313, 1, '{\"question_text\":\"Что такое элемент <canvas>?\",\"answers\":[{\"id\":1239,\"answer\":\"Область для рисования 2D\\/3D графики с помощью JavaScript\",\"is_correct\":1},{\"id\":1240,\"answer\":\"Специальный фильтр для автоматической обработки фотографий\",\"is_correct\":0},{\"id\":1241,\"answer\":\"Тип контейнера, который может хранить только файлы формата .psd\",\"is_correct\":0},{\"id\":1242,\"answer\":\"Инструмент для создания таблиц с неограниченным числом строк\",\"is_correct\":0}]}', '2026-05-16 10:44:34'),
(278, 31, 332, 2, '{\"question_text\":\"Что такое \\\"Схлопывание границ\\\" в контексте чистого HTML?\",\"answers\":[{\"id\":1315,\"answer\":\"Объединение вертикальных отступов соседних блоков в один\",\"is_correct\":1},{\"id\":1316,\"answer\":\"Ошибка, при которой текст вылазит за пределы экрана\",\"is_correct\":0},{\"id\":1317,\"answer\":\"Процесс удаления всех рамок (borders) у таблиц\",\"is_correct\":0},{\"id\":1318,\"answer\":\"Метод автоматического уменьшения размера шрифта\",\"is_correct\":0}]}', '2026-05-16 10:44:34'),
(279, 31, 329, 3, '{\"question_text\":\"Что такое ARIA-роли (role=\\\"...\\\")?\",\"answers\":[{\"id\":1303,\"answer\":\"Атрибуты для улучшения доступности сайта (скринридеры)\",\"is_correct\":1},{\"id\":1304,\"answer\":\"Список всех ролей сотрудников внутри компании-разработчика\",\"is_correct\":0},{\"id\":1305,\"answer\":\"Специальный метод для настройки анимаций через HTML\",\"is_correct\":0},{\"id\":1306,\"answer\":\"Протокол для передачи аудио и видео данных в реальном времени\",\"is_correct\":0}]}', '2026-05-16 10:44:34'),
(280, 31, 308, 4, '{\"question_text\":\"Сколько тегов <main> может быть на странице?\",\"answers\":[{\"id\":1219,\"answer\":\"Только один\",\"is_correct\":1},{\"id\":1220,\"answer\":\"Не более десяти\",\"is_correct\":0},{\"id\":1221,\"answer\":\"Ровно три: в начале, в середине и в конце\",\"is_correct\":0},{\"id\":1222,\"answer\":\"Любое количество, это не ограничено правилами\",\"is_correct\":0}]}', '2026-05-16 10:44:34'),
(281, 31, 327, 5, '{\"question_text\":\"Разница между тегами <progress> и <meter>?\",\"answers\":[{\"id\":1295,\"answer\":\"progress для хода выполнения, meter для статических измерений\",\"is_correct\":1},{\"id\":1296,\"answer\":\"meter используется только в играх, а progress в бэкенде\",\"is_correct\":0},{\"id\":1297,\"answer\":\"progress работает медленнее, так как требует JS\",\"is_correct\":0},{\"id\":1298,\"answer\":\"Разницы нет, это два названия одного и того же индикатора\",\"is_correct\":0}]}', '2026-05-16 10:44:34'),
(282, 31, 333, 6, '{\"question_text\":\"Что такое атрибуты async и defer для тега <script>?\",\"answers\":[{\"id\":1319,\"answer\":\"async — выполнение сразу, defer — после парсинга всего HTML\",\"is_correct\":1},{\"id\":1320,\"answer\":\"defer работает только в Internet Explorer 6, async — везде\",\"is_correct\":0},{\"id\":1321,\"answer\":\"Эти атрибуты нужны для подключения стилей CSS, а не скриптов\",\"is_correct\":0},{\"id\":1322,\"answer\":\"async делает код платным, а defer оставляет его бесплатным\",\"is_correct\":0}]}', '2026-05-16 10:44:34'),
(283, 31, 301, 7, '{\"question_text\":\"Что такое Image Map?\",\"answers\":[{\"id\":1191,\"answer\":\"Тег <map> для создания нескольких кликабельных зон на одной картинке\",\"is_correct\":1},{\"id\":1192,\"answer\":\"Карта всех серверов, на которых хранятся изображения вашего сайта\",\"is_correct\":0},{\"id\":1193,\"answer\":\"Специальный формат изображений со встроенной GPS-навигацией\",\"is_correct\":0},{\"id\":1194,\"answer\":\"Метод автоматической группировки всех картинок в одну папку\",\"is_correct\":0}]}', '2026-05-16 10:44:34'),
(294, 33, 318, 1, '{\"question_text\":\"Зачем нужен глобальный атрибут lang у тега html?\",\"answers\":[{\"id\":1259,\"answer\":\"Указывает язык контента для скринридеров и браузера\",\"is_correct\":1},{\"id\":1260,\"answer\":\"Определяет основной язык программирования, на котором написан сайт\",\"is_correct\":0},{\"id\":1261,\"answer\":\"Заставляет браузер автоматически переводить страницу на русский\",\"is_correct\":0},{\"id\":1262,\"answer\":\"Атрибут для настройки часового пояса пользователя\",\"is_correct\":0}]}', '2026-05-16 10:46:21'),
(295, 33, 309, 2, '{\"question_text\":\"Зачем нужны теги <section> и <article>?\",\"answers\":[{\"id\":1223,\"answer\":\"section для групп контента, article для независимых цельных блоков\",\"is_correct\":1},{\"id\":1224,\"answer\":\"article используется только для газетных статей в интернете\",\"is_correct\":0},{\"id\":1225,\"answer\":\"section ускоряет загрузку страницы, а article замедляет её\",\"is_correct\":0},{\"id\":1226,\"answer\":\"Это устаревшие теги, которые заменили на <div> в HTML5\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(296, 33, 321, 3, '{\"question_text\":\"Разница между тегами <ul>, <ol> и <dl>?\",\"answers\":[{\"id\":1271,\"answer\":\"ul — маркеры, ol — числа, dl — список определений\",\"is_correct\":1},{\"id\":1272,\"answer\":\"ul — для картинок, ol — для ссылок, dl — для текста\",\"is_correct\":0},{\"id\":1273,\"answer\":\"ol всегда работает в 10 раз быстрее, чем ul\",\"is_correct\":0},{\"id\":1274,\"answer\":\"DL — это старый формат, который запрещен в HTML5\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(297, 33, 305, 4, '{\"question_text\":\"Зачем нужен тег <label> и атрибут for?\",\"answers\":[{\"id\":1207,\"answer\":\"Для связи текста с полем ввода и улучшения доступности\",\"is_correct\":1},{\"id\":1208,\"answer\":\"Чтобы добавить красивую рамку вокруг поля ввода через HTML\",\"is_correct\":0},{\"id\":1209,\"answer\":\"Этот тег нужен только для вставки логотипа компании в форму\",\"is_correct\":0},{\"id\":1210,\"answer\":\"Для защиты формы от спам-ботов без использования капчи\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(298, 33, 322, 5, '{\"question_text\":\"Что такое тег <iframe>?\",\"answers\":[{\"id\":1275,\"answer\":\"Позволяет встроить одну HTML-страницу внутрь другой\",\"is_correct\":1},{\"id\":1276,\"answer\":\"Управляет скоростью интернета на стороне пользователя\",\"is_correct\":0},{\"id\":1277,\"answer\":\"Специальный фильтр для защиты зрения программиста (Apple Style)\",\"is_correct\":0},{\"id\":1278,\"answer\":\"Метод автоматического удаления всех Apple устройств из сети\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(299, 33, 330, 6, '{\"question_text\":\"Разница между тегами <time> и простым текстом?\",\"answers\":[{\"id\":1307,\"answer\":\"time позволяет машинам понимать дату через атрибут datetime\",\"is_correct\":1},{\"id\":1308,\"answer\":\"Тег <time> автоматически останавливает время на сайте\",\"is_correct\":0},{\"id\":1309,\"answer\":\"time работает в 10 раз быстрее обычного параграфа <p>\",\"is_correct\":0},{\"id\":1310,\"answer\":\"Использование тега <time> защищает сайт от вирусов и атак\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(300, 33, 306, 7, '{\"question_text\":\"Что такое семантическая верстка?\",\"answers\":[{\"id\":1211,\"answer\":\"Использование тегов согласно их смыслу (header, main, section)\",\"is_correct\":1},{\"id\":1212,\"answer\":\"Верстка сайта только с помощью тегов <div> и <span>\",\"is_correct\":0},{\"id\":1213,\"answer\":\"Автоматический перевод сайта на 100 языков через нейросеть\",\"is_correct\":0},{\"id\":1214,\"answer\":\"Процесс удаления всех CSS-стилей из готового проекта\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(301, 33, 312, 8, '{\"question_text\":\"Что делает <meta name=\\\"viewport\\\">?\",\"answers\":[{\"id\":1235,\"answer\":\"Управляет масштабированием и отображением на мобильных устройствах\",\"is_correct\":1},{\"id\":1236,\"answer\":\"Делает скриншот экрана пользователя при входе на сайт\",\"is_correct\":0},{\"id\":1237,\"answer\":\"Позволяет пользователю смотреть видео через VR-очки\",\"is_correct\":0},{\"id\":1238,\"answer\":\"Эта команда удаляет все картинки со страницы для экономии трафика\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(302, 33, 311, 9, '{\"question_text\":\"Атрибуты тега <video>?\",\"answers\":[{\"id\":1231,\"answer\":\"src, controls, autoplay, loop, muted\",\"is_correct\":1},{\"id\":1232,\"answer\":\"href, target, title, alt, download\",\"is_correct\":0},{\"id\":1233,\"answer\":\"color, size, font, weight, style\",\"is_correct\":0},{\"id\":1234,\"answer\":\"id, class, name, value, placeholder\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(303, 33, 307, 10, '{\"question_text\":\"Разница между <strong> и <b>?\",\"answers\":[{\"id\":1215,\"answer\":\"Strong несет смысловую важность, B — только визуальное выделение\",\"is_correct\":1},{\"id\":1216,\"answer\":\"B работает только в Safari, а Strong — во всех браузерах\",\"is_correct\":0},{\"id\":1217,\"answer\":\"Тег Strong делает текст красным, а B — черным\",\"is_correct\":0},{\"id\":1218,\"answer\":\"Strong используется для заголовков, а B — для основного текста\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(304, 34, 306, 1, '{\"question_text\":\"Что такое семантическая верстка?\",\"answers\":[{\"id\":1211,\"answer\":\"Использование тегов согласно их смыслу (header, main, section)\",\"is_correct\":1},{\"id\":1212,\"answer\":\"Верстка сайта только с помощью тегов <div> и <span>\",\"is_correct\":0},{\"id\":1213,\"answer\":\"Автоматический перевод сайта на 100 языков через нейросеть\",\"is_correct\":0},{\"id\":1214,\"answer\":\"Процесс удаления всех CSS-стилей из готового проекта\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(305, 34, 323, 2, '{\"question_text\":\"Зачем нужен тег <figure> и <figcaption>?\",\"answers\":[{\"id\":1279,\"answer\":\"Для группировки контента (картинка, код) и добавления подписи\",\"is_correct\":1},{\"id\":1280,\"answer\":\"Для создания трехмерных моделей внутри браузера\",\"is_correct\":0},{\"id\":1281,\"answer\":\"Специальный формат для хранения зашифрованных паролей\",\"is_correct\":0},{\"id\":1282,\"answer\":\"Метод принудительной очистки кэша изображений\",\"is_correct\":0}]}', '2026-05-16 10:46:22'),
(306, 34, 312, 3, '{\"question_text\":\"Что делает <meta name=\\\"viewport\\\">?\",\"answers\":[{\"id\":1235,\"answer\":\"Управляет масштабированием и отображением на мобильных устройствах\",\"is_correct\":1},{\"id\":1236,\"answer\":\"Делает скриншот экрана пользователя при входе на сайт\",\"is_correct\":0},{\"id\":1237,\"answer\":\"Позволяет пользователю смотреть видео через VR-очки\",\"is_correct\":0},{\"id\":1238,\"answer\":\"Эта команда удаляет все картинки со страницы для экономии трафика\",\"is_correct\":0}]}', '2026-05-16 10:46:23'),
(307, 34, 325, 4, '{\"question_text\":\"Зачем нужны атрибуты readonly и disabled?\",\"answers\":[{\"id\":1287,\"answer\":\"readonly шлет данные на сервер, disabled — полностью отключает поле\",\"is_correct\":1},{\"id\":1288,\"answer\":\"disabled используется только для кнопок, а readonly только для текста\",\"is_correct\":0},{\"id\":1289,\"answer\":\"При использовании disabled сайт начинает потреблять меньше памяти\",\"is_correct\":0},{\"id\":1290,\"answer\":\"readonly делает текст невидимым, а disabled — прозрачным\",\"is_correct\":0}]}', '2026-05-16 10:46:23'),
(308, 34, 295, 5, '{\"question_text\":\"Что такое валидный HTML?\",\"answers\":[{\"id\":1175,\"answer\":\"Код, написанный без ошибок согласно спецификации W3C\",\"is_correct\":1},{\"id\":1176,\"answer\":\"HTML код, который прошел проверку антивирусом Касперского\",\"is_correct\":0},{\"id\":1177,\"answer\":\"Специальный платный формат разметки для бизнес-сайтов\",\"is_correct\":0},{\"id\":1178,\"answer\":\"Разметка, в которой используются только теги <div>\",\"is_correct\":0}]}', '2026-05-16 10:46:23'),
(309, 34, 309, 6, '{\"question_text\":\"Зачем нужны теги <section> и <article>?\",\"answers\":[{\"id\":1223,\"answer\":\"section для групп контента, article для независимых цельных блоков\",\"is_correct\":1},{\"id\":1224,\"answer\":\"article используется только для газетных статей в интернете\",\"is_correct\":0},{\"id\":1225,\"answer\":\"section ускоряет загрузку страницы, а article замедляет её\",\"is_correct\":0},{\"id\":1226,\"answer\":\"Это устаревшие теги, которые заменили на <div> в HTML5\",\"is_correct\":0}]}', '2026-05-16 10:46:23'),
(310, 34, 322, 7, '{\"question_text\":\"Что такое тег <iframe>?\",\"answers\":[{\"id\":1275,\"answer\":\"Позволяет встроить одну HTML-страницу внутрь другой\",\"is_correct\":1},{\"id\":1276,\"answer\":\"Управляет скоростью интернета на стороне пользователя\",\"is_correct\":0},{\"id\":1277,\"answer\":\"Специальный фильтр для защиты зрения программиста (Apple Style)\",\"is_correct\":0},{\"id\":1278,\"answer\":\"Метод автоматического удаления всех Apple устройств из сети\",\"is_correct\":0}]}', '2026-05-16 10:46:23'),
(311, 34, 303, 8, '{\"question_text\":\"GET vs POST в формах?\",\"answers\":[{\"id\":1199,\"answer\":\"GET передает данные в URL, POST — в теле запроса\",\"is_correct\":1},{\"id\":1200,\"answer\":\"POST используется для картинок, а GET только для текста\",\"is_correct\":0},{\"id\":1201,\"answer\":\"GET работает в 10 раз быстрее, чем POST, во всех браузерах\",\"is_correct\":0},{\"id\":1202,\"answer\":\"Разницы нет, это старые названия для протокола HTTP 1.0\",\"is_correct\":0}]}', '2026-05-16 10:46:23'),
(312, 34, 319, 9, '{\"question_text\":\"Разница между тегами <button> и <input type=\\\"button\\\">?\",\"answers\":[{\"id\":1263,\"answer\":\"<button> может содержать вложенные теги (текст + иконка)\",\"is_correct\":1},{\"id\":1264,\"answer\":\"<input type=\\\"button\\\"> работает только на мобильных устройствах\",\"is_correct\":0},{\"id\":1265,\"answer\":\"<button> — это платный тег, а <input> — бесплатный\",\"is_correct\":0},{\"id\":1266,\"answer\":\"Разницы нет, это два названия одного и того же элемента\",\"is_correct\":0}]}', '2026-05-16 10:46:23'),
(313, 34, 305, 10, '{\"question_text\":\"Зачем нужен тег <label> и атрибут for?\",\"answers\":[{\"id\":1207,\"answer\":\"Для связи текста с полем ввода и улучшения доступности\",\"is_correct\":1},{\"id\":1208,\"answer\":\"Чтобы добавить красивую рамку вокруг поля ввода через HTML\",\"is_correct\":0},{\"id\":1209,\"answer\":\"Этот тег нужен только для вставки логотипа компании в форму\",\"is_correct\":0},{\"id\":1210,\"answer\":\"Для защиты формы от спам-ботов без использования капчи\",\"is_correct\":0}]}', '2026-05-16 10:46:23');
