INSERT INTO `questions` (`id`, `question`, `explanation`, `route_id`, `language_id`, `topic_id`, `experience_level_id`, `difficulty`, `multiple_answers`, `is_active`, `created_at`, `updated_at`) VALUES
(2, 'Что такое декоратор в Python?', 'Это функция, которая расширяет возможности другой функции.', 1, 1, NULL, 2, 2, 0, 1, '2026-05-13 09:31:08', '2026-05-13 09:31:08'),
(3, 'В чем разница между stack и heap?', 'Стек используется для статического выделения памяти, куча - для динамического.', 1, 2, NULL, 3, 3, 0, 1, '2026-05-13 09:31:09', '2026-05-13 09:31:09'),
(5, 'Что такое последовательность (Sequence)?', 'Итерабельный объект, поддерживающий доступ по индексу (__getitem__) и знающий свою длину (__len__). Примеры: list, tuple, str, bytes, range.', 1, 1, 1, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(6, 'Какие виды строк есть в Python 3?', 'В Python 3 есть только тип str, который представляет собой Юникод. Для работы с сырыми байтами используется тип bytes.', 1, 1, 1, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(7, 'Можно ли изменить символ в строке по индексу?', 'Нет, строки в Python неизменяемы (immutable). Любая операция изменения создает новую строку.', 1, 1, 1, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(8, 'Как эффективно соединить список строк в одну?', 'С помощью метода \"\".join(список). Это быстрее, чем сложение через \"+\", так как память выделяется один раз.', 1, 1, 1, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(9, 'Что такое кодирование (encoding) и декодирование (decoding)?', 'Encoding — перевод Юникода в байты (str.encode()). Decoding — восстановление Юникода из байт (bytes.decode()).', 1, 1, 1, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(10, 'Что такое диапазон (range)?', 'Неизменяемая последовательность чисел. Не хранит все числа в памяти, а вычисляет их на лету. Параметры: start, stop, step.', 1, 1, 1, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(11, 'Что такое \"утиная типизация\" (Duck Typing)?', 'Если объект ведет себя как утка (имеет нужные методы), то Python считает его уткой, независимо от его реального класса.', 1, 1, 1, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(12, 'Чем отличаются globals() и locals()?', 'globals() возвращает словарь переменных глобальной области видимости модуля, locals() — текущей локальной (например, внутри функции).', 1, 1, 1, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(13, 'Как проверить файл .py на ошибки без запуска?', 'С помощью утилиты py_compile: python -m py_compile file.py.', 1, 1, 1, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(14, 'Чем список (list) отличается от кортежа (tuple)?', 'Список — изменяемый массив указателей. Кортеж — неизменяемый массив. Кортежи легче по памяти и быстрее в доступе.', 1, 1, 2, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(15, 'Как сделать список уникальным с сохранением порядка?', 'Использовать list(dict.fromkeys(my_list)). Множество set() не гарантирует сохранение порядка.', 1, 1, 2, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(16, 'Как сравниваются последовательности?', 'Лексикографически: сначала типы, потом длины, затем поэлементно до первого отличия.', 1, 1, 2, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(17, 'Как понять, что объект хешируемый?', 'Объект хешируемый, если у него есть метод __hash__ и его значение не меняется во время жизни. Все неизменяемые типы (int, str, frozenset) хешируемые.', 1, 1, 2, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(18, 'Что такое множество (set)?', 'Неупорядоченная коллекция уникальных хешируемых объектов. Поддерживает операции пересечения, объединения и разности.', 1, 1, 2, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(19, 'Какие нюансы использования float как ключей словаря?', 'Из-за приближенного хранения float в памяти (0.1 + 0.2 != 0.3), поиск по таким ключам может быть непредсказуемым. Не рекомендуется.', 1, 1, 2, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(20, 'Что возвращают методы dict.keys(), values(), items()?', 'Они возвращают объекты-представления (views). Они динамически отражают изменения словаря без копирования данных.', 1, 1, 2, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(21, 'Как работает хэш-таблица внутри dict?', 'Используется разреженный массив (ячейки-бакеты). Индекс вычисляется из хэша ключа. При коллизиях используется открытая адресация.', 1, 1, 2, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(22, 'Что такое коллизия хэширования?', 'Ситуация, когда два разных ключа имеют одинаковый хэш или попадают в один индекс таблицы. Python разрешает их методом открытой адресации.', 1, 1, 2, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(23, 'Где быстрее поиск: в списке или в словаре?', 'В словаре и множестве O(1), в списке O(n). Для коллекций более 5 элементов словарь всегда быстрее.', 1, 1, 2, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(24, 'В чем разница между *args и **kwargs?', '*args — кортеж позиционных аргументов, **kwargs — словарь именованных. Позволяют функции принимать любое число параметров.', 1, 1, 3, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(25, 'Почему нельзя использовать mutable объект как default value?', 'Он создается один раз при определении функции. Все вызовы будут модифицировать один и тот же объект в памяти.', 1, 1, 3, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(26, 'Что такое лямбда-функция?', 'Анонимная функция из одного выражения. Не может содержать операторы (if/yield/pass).', 1, 1, 3, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(27, 'Что такое замыкание (closure)?', 'Внутренняя функция, которая ссылается на переменные из внешней области видимости, даже когда внешняя функция завершила работу.', 1, 1, 3, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(28, 'Что такое каррирование (Currying)?', 'Преобразование функции от многих аргументов в набор функций, каждая из которых берет ровно один аргумент.', 1, 1, 3, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(29, 'Что делает функция reduce из functools?', 'Применяет функцию к парам элементов последовательности, сворачивая её в одно единственное значение.', 1, 1, 3, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(30, 'Зачем нужен декоратор @functools.lru_cache?', 'Для мемоизации: он сохраняет результаты вызовов функции, чтобы не вычислять их повторно для тех же аргументов.', 1, 1, 3, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(31, 'Что такое \"объект первого класса\"?', 'Сущность, которую можно передать в функцию, вернуть из неё или присвоить переменной. В Python функции — объекты первого класса.', 1, 1, 3, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(32, 'Как в классе сослаться на родителя?', 'С помощью функции super(). Она вызывает следующий класс в цепочке MRO.', 1, 1, 4, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(33, 'Что такое MRO и алгоритм C3?', 'Порядок разрешения методов. Алгоритм C3 гарантирует, что каждый родитель вызывается один раз и сохраняется локальный приоритет.', 1, 1, 4, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(34, 'Что такое \"Diamond Problem\"?', 'Проблема ромбовидного наследования, когда один класс наследуется от двух, имеющих общего предка. Решается через MRO.', 1, 1, 4, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(35, 'Что такое миксины (Mixins)?', 'Классы-помощники, которые добавляют функциональность другим классам через множественное наследование, не имея собственного состояния.', 1, 1, 4, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(36, 'В чем смысл атрибута __slots__?', 'Жестко фиксирует набор полей класса, запрещая создание __dict__. Экономит память и ускоряет доступ к атрибутам.', 1, 1, 4, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(37, 'Разница между _var и __var?', '_var — соглашение о приватности. __var — запуск механизма name mangling (имя меняется на _ClassName__var) для защиты от переопределения.', 1, 1, 4, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(38, 'В какой последовательности выполняются __new__ и __init__?', 'Сначала __new__ (создание объекта), затем __init__ (инициализация созданного объекта).', 1, 1, 4, 3, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(39, 'Что такое дескрипторы?', 'Объекты, определяющие поведение при доступе к атрибуту другого объекта через методы __get__, __set__, __delete__.', 1, 1, 4, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(40, 'Что такое метаклассы?', 'Классы, которые создают другие классы. type — базовый метакласс Python. Позволяют менять логику создания классов.', 1, 1, 4, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(41, 'Что такое итерабельный объект (Iterable)?', 'Любой объект, реализующий метод __iter__ (возвращает итератор) или __getitem__ (доступ по индексу).', 1, 1, 5, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(42, 'Что такое итератор?', 'Объект, представляющий поток данных. Имеет метод __next__, который возвращает элементы по одному или вызывает StopIteration.', 1, 1, 5, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(43, 'Чем генератор отличается от списка?', 'Генератор не хранит все элементы в памяти, а вычисляет их лениво (по одному). Его можно обойти только один раз.', 1, 1, 5, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(44, 'Что делает оператор yield?', 'Замораживает состояние функции, возвращает значение и ждет следующего вызова __next__, чтобы продолжить работу.', 1, 1, 5, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(45, 'Что такое yield from?', 'Делегирует выполнение подгенератору. Позволяет прозрачно передавать значения и ошибки между вложенными генераторами.', 1, 1, 5, 3, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(46, 'Что такое контекстный менеджер?', 'Объект с методами __enter__ и __exit__. Используется в блоке with для автоматического управления ресурсами.', 1, 1, 5, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(47, 'Можно ли извлечь элемент генератора по индексу?', 'Нет. Генераторы не поддерживают случайный доступ (индексацию), только последовательный перебор.', 1, 1, 5, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(48, 'Что такое GIL?', 'Блокировка, гарантирующая, что только один поток Python выполняет байт-код одновременно. Упрощает работу с памятью, но мешает CPU-bound задачам.', 1, 1, 6, 3, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(49, 'Как GIL влияет на I/O задачи?', 'Почти не влияет. При системных вызовах (сеть, диск) поток отпускает GIL, позволяя другим потокам работать.', 1, 1, 6, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(50, 'threading vs multiprocessing?', 'Threading: общая память, один процесс, мешает GIL. Multiprocessing: разная память, разные процессы, обходит GIL.', 1, 1, 6, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(51, 'Что такое гонка условий (Race Condition)?', 'Ситуация, когда результат зависит от порядка выполнения потоков. Решается мьютексами (Lock) и семафорами.', 1, 1, 6, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(52, 'Что такое \"Зеленые потоки\" (Greenlets)?', 'Легковесные потоки на уровне пользователя, управляемые самой программой, а не ОС. Используются в gevent.', 1, 1, 6, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(53, 'Что такое корутина (сопрограмма)?', 'Функция, выполнение которой можно приостановить и возобновить. В Python объявляется через async def.', 1, 1, 7, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(54, 'Что делает ключевое слово await?', 'Приостанавливает выполнение текущей корутины, пока не завершится асинхронная операция, отдавая управление в Event Loop.', 1, 1, 7, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(55, 'Что такое Event Loop?', 'Бесконечный цикл, который следит за асинхронными задачами и переключает выполнение между ними, когда приходят данные из сети/диска.', 1, 1, 7, 3, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(56, 'Почему асинхронность бесполезна для вычислений?', 'Потому что Event Loop работает в одном потоке. Тяжелая математика заблокирует цикл и весь сервис \"встанет\".', 1, 1, 7, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(57, 'Как работает сборщик мусора (GC)?', 'Основной механизм — подсчет ссылок. Дополнительный — поиск циклических ссылок через разделение объектов на 3 поколения.', 1, 1, 8, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(58, 'Что такое утечка памяти в Python?', 'Ситуация, когда объекты больше не нужны, но на них остаются ссылки (например, в глобальных списках), и GC не может их удалить.', 1, 1, 8, 3, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(59, 'Что такое интернирование строк?', 'Механизм хранения одинаковых строк в одном месте памяти. Работает для констант и коротких строк (до 20 символов).', 1, 1, 8, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(60, 'Что такое файлы .pyc?', 'Скомпилированный байт-код. Позволяет не тратить время на парсинг исходного кода при повторном запуске.', 1, 1, 8, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(61, 'Что такое виртуальное окружение (venv)?', 'Изолированная папка с интерпретатором и библиотеками, чтобы зависимости разных проектов не конфликтовали.', 1, 1, 8, 1, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(62, 'Принцип KISS?', 'Keep It Simple, Stupid. Делай код максимально простым, не усложняй архитектуру без необходимости.', 1, 1, 8, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(63, 'Принцип DRY?', 'Don\'t Repeat Yourself. Выноси повторяющийся код в функции или классы.', 1, 1, 8, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(64, 'Принцип YAGNI?', 'You Ain\'t Gonna Need It. Не пиши код, который \"возможно понадобится в будущем\".', 1, 1, 8, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(65, 'Что такое SOLID?', '5 принципов ООП: единственная ответственность, открытость/закрытость, подстановка Лисков, разделение интерфейса, инверсия зависимостей.', 1, 1, 8, 3, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(66, 'Что такое Unit-тест?', 'Тестирование минимальной части кода (одной функции или метода) в полной изоляции от БД и сети.', 1, 1, 9, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(67, 'Что такое Mocking?', 'Подмена реальных объектов (базы данных, API) пустышками-заглушками для чистоты и скорости тестов.', 1, 1, 9, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(68, 'Разница между интеграционным и функциональным тестом?', 'Интеграционные проверяют связь между модулями (код + БД). Функциональные проверяют работу всей фичи с точки зрения пользователя.', 1, 1, 9, 3, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(69, 'Что такое Smoke Test?', 'Минимальный набор тестов, проверяющий, что приложение хотя бы запускается и основные функции работают.', 1, 1, 9, 2, 1, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(70, 'Что такое регрессионное тестирование?', 'Повторный запуск тестов после исправлений, чтобы убедиться, что новые правки не сломали старый функционал.', 1, 1, 9, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(71, 'Зачем нужен pdb?', 'Интерактивный отладчик. Позволяет ставить брейкпоинты, смотреть значения переменных и выполнять код построчно.', 1, 1, 9, 2, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(72, 'Что такое дескрипторы данных и недоступные дескрипторы?', 'Data descriptors имеют __set__. Non-data descriptors имеют только __get__. Это влияет на приоритет поиска в __dict__.', 1, 1, 8, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(73, 'Как работает менеджер памяти для маленьких объектов (<512 байт)?', 'Python выделяет арены (256КБ), которые делятся на пулы (4КБ) и блоки. Это минимизирует обращения к ОС.', 1, 1, 8, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(74, 'Разница между Monkey Patching и обычным расширением?', 'Monkey Patching — это замена атрибутов или методов объекта прямо во время выполнения программы (runtime).', 1, 1, 4, 4, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(75, 'Что такое транзитивные зависимости?', 'Это зависимости твоих зависимостей. Если ты ставишь библиотеку A, а ей нужна библиотека B, то B — транзитивная зависимость.', 1, 1, 8, 3, 2, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(76, 'Как работает интернирование целых чисел?', 'Python заранее создает объекты для чисел от -5 до 256. Они всегда ссылаются на одно и то же место в памяти.', 1, 1, 8, 3, 3, 0, 1, '2026-05-13 09:56:30', '2026-05-13 09:56:30'),
(77, 'Что такое указатель?', 'Переменная, значением которой является адрес ячейки памяти. Позволяет напрямую работать с памятью.', 1, 2, 10, 1, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(78, 'Разница между malloc и calloc?', 'malloc выделяет память, не инициализируя её. calloc обнуляет выделенную память.', 1, 2, 10, 1, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(79, 'Что делает ключевое слово static для локальной переменной?', 'Продлевает жизнь переменной до конца программы, сохраняя её значение между вызовами функции.', 1, 2, 10, 2, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(80, 'Что такое объединение (union)?', 'Тип данных, где все члены делят одну и ту же область памяти. Размер union равен размеру самого большого члена.', 1, 2, 10, 2, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(81, 'Разница между константой и макросом #define?', 'const имеет тип и проверяется компилятором. #define — это просто текстовая замена препроцессором без проверки типов.', 1, 2, 10, 1, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(82, 'Что такое выравнивание (alignment) в структурах?', 'Процесс размещения данных по адресам, кратным их размеру, для ускорения доступа процессора к памяти.', 1, 2, 10, 2, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(83, 'В чем разница между стеком (stack) и кучей (heap)?', 'Стек — быстрый, управляется автоматически. Куча — большая, управляется программистом вручную через new/delete.', 1, 2, 11, 2, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(84, 'Разница между указателем и ссылкой?', 'Указатель может быть NULL и его можно переназначить. Ссылка обязана быть инициализирована и не может быть изменена.', 1, 2, 11, 2, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(85, 'Что будет, если вызвать delete у объекта, созданного через new[]?', 'Неопределенное поведение (Undefined Behavior). Для массивов всегда нужно использовать delete[].', 1, 2, 11, 2, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(86, 'Что такое умный указатель (Smart Pointer)?', 'Класс-обертка над сырым указателем, реализующий RAII (автоматическое освобождение памяти).', 1, 2, 11, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(87, 'Как работает std::unique_ptr?', 'Владеет объектом единолично. Запрещает копирование, разрешает только перемещение (std::move).', 1, 2, 11, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(88, 'Как работает std::shared_ptr?', 'Использует счетчик ссылок. Объект удаляется, когда последний shared_ptr на него уничтожается.', 1, 2, 11, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(89, 'Зачем нужен std::weak_ptr?', 'Для решения проблемы циклических ссылок у shared_ptr. Не увеличивает счетчик владения.', 1, 2, 11, 3, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(90, 'Что такое RAII?', 'Resource Acquisition Is Initialization. Ресурс захватывается в конструкторе и гарантированно освобождается в деструкторе.', 1, 2, 11, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(91, 'Что такое Placement new?', 'Позволяет создать объект в уже выделенной заранее области памяти по конкретному адресу.', 1, 2, 11, 4, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(92, 'В чем разница между struct и class в C++?', 'В доступе по умолчанию. В struct — public, в class — private.', 1, 2, 12, 1, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(93, 'Для чего нужен виртуальный деструктор?', 'Чтобы при удалении наследника через указатель на базовый класс вызвался деструктор наследника, иначе будет утечка.', 1, 2, 12, 2, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(94, 'Что такое чисто виртуальная функция?', 'Функция с синтаксисом = 0. Делает класс абстрактным. Её реализация обязательна в наследниках.', 1, 2, 12, 2, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(95, 'Что такое vtable и vptr?', 'vtable — таблица адресов виртуальных функций класса. vptr — указатель внутри объекта на эту таблицу.', 1, 2, 12, 3, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(96, 'Как работает множественное наследование?', 'Класс наследует поля и методы от нескольких родителей. Может привести к Diamond Problem.', 1, 2, 12, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(97, 'Зачем нужно виртуальное наследование?', 'Для решения проблемы ромбовидного наследования: чтобы общая база создавалась в единственном экземпляре.', 1, 2, 12, 3, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(98, 'Что такое инкапсуляция в С++?', 'Механизм скрытия полей через private/protected и предоставление доступа через public-методы.', 1, 2, 12, 2, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(99, 'Разница между Overloading и Overriding?', 'Overloading — функции с тем же именем, но разными аргументами. Overriding — переопределение виртуальной функции наследником.', 1, 2, 12, 2, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(100, 'Что такое инстанциация шаблона?', 'Процесс создания компилятором конкретного кода класса или функции на основе предоставленных типов.', 1, 2, 13, 2, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(101, 'Что такое специализация шаблона?', 'Определение особой реализации шаблона для конкретного типа (например, для bool или char*).', 1, 2, 13, 3, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(102, 'Что такое SFINAE?', 'Substitution Failure Is Not An Error. Если компилятор не может подставить тип в шаблон, он не выдает ошибку, а ищет другой шаблон.', 1, 2, 13, 4, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(103, 'Что такое PIMPL?', 'Pointer to Implementation. Паттерн скрытия деталей реализации через указатель на структуру в private секции.', 1, 2, 13, 3, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(104, 'std::vector vs std::list?', 'Vector — массив (быстрый доступ, медленная вставка в начало). List — связный список (медленный доступ, быстрая вставка).', 1, 2, 14, 2, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(105, 'Как работает std::map?', 'Обычно реализован как красно-черное дерево (сбалансированное). Поиск за O(log n).', 1, 2, 14, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(106, 'std::map vs std::unordered_map?', 'Map — дерево, элементы отсортированы. Unordered_map — хэш-таблица, доступ в среднем за O(1).', 1, 2, 14, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(107, 'Что такое инвалидация итераторов?', 'Состояние, когда после изменения контейнера (например, push_back в вектор) старые итераторы становятся некорректными.', 1, 2, 14, 3, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(108, 'Что такое Deadlock?', 'Взаимная блокировка двух и более потоков, ожидающих ресурсы, занятые друг другом.', 1, 2, 15, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(109, 'Мьютекс (mutex) vs Семафор (semaphore)?', 'Мьютекс — владелец один. Семафор — это счетчик, может разрешать доступ нескольким потокам одновременно.', 1, 2, 15, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(110, 'Что такое Race Condition?', 'Состояние гонки: когда результат зависит от непредсказуемого порядка выполнения потоков.', 1, 2, 15, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(111, 'Что такое атомарная операция (std::atomic)?', 'Операция, которая выполняется за один такт процессора без возможности прерывания другим потоком.', 1, 2, 15, 3, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(112, 'Что такое Move-семантика?', 'Передача владения ресурсом от одного объекта другому без копирования (std::move).', 1, 2, 17, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(113, 'Разница между lvalue и rvalue?', 'lvalue — объект с именем и адресом. rvalue — временный объект без имени.', 1, 2, 17, 3, 3, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(114, 'Что делает ключевое слово auto?', 'Автоматически выводит тип переменной из инициализатора во время компиляции.', 1, 2, 17, 2, 1, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(115, 'Что такое лямбда-выражение?', 'Анонимная функция, объявляемая прямо в месте использования. Может захватывать переменные контекста.', 1, 2, 17, 2, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(116, 'constexpr vs const?', 'const — значение нельзя менять. constexpr — значение гарантированно вычисляется во время компиляции.', 1, 2, 17, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(117, 'Что такое std::variant (C++17)?', 'Типобезопасное объединение (union), которое знает, какой тип данных в нем лежит в данный момент.', 1, 2, 17, 3, 2, 0, 1, '2026-05-13 10:10:32', '2026-05-13 10:10:32'),
(118, 'Что означает ключевое слово volatile?', 'Указывает компилятору, что значение переменной может измениться извне (например, другим потоком или железом), и запрещает оптимизацию доступа к ней.', 1, 2, 10, 3, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(119, 'Зачем нужен extern \"C\"?', 'Для предотвращения искажения имен (name mangling) компилятором C++, чтобы можно было линковать код с библиотеками, написанными на C.', 1, 2, 10, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(120, 'Что такое битовые поля (bit-fields)?', 'Позволяют задавать размер членов структуры в битах, что экономит память при работе с флагами или аппаратными регистрами.', 1, 2, 10, 3, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(121, 'В чем разница между enum и enum class (scoped enum)?', 'Обычный enum экспортирует имена в окружающую область видимости и приводится к int. enum class строго типизирован и требует указания имени типа.', 1, 2, 10, 2, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(122, 'Почему std::make_shared лучше, чем shared_ptr(new T)?', 'make_shared делает одну аллокацию памяти вместо двух (для объекта и для блока управления), что быстрее и безопаснее.', 1, 2, 11, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(123, 'Что такое переполнение стека (Stack Overflow)?', 'Исчерпание памяти стека, обычно вызванное бесконечной рекурсией или созданием слишком больших локальных массивов.', 1, 2, 11, 2, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(124, 'Как продлить время жизни временного объекта?', 'С помощью константной ссылки lvalue (const T&) или rvalue-ссылки (T&&).', 1, 2, 11, 3, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(125, 'Что такое сегментация памяти (Segfault)?', 'Ошибка, когда программа пытается обратиться к области памяти, которая ей не принадлежит (например, разыменование NULL).', 1, 2, 11, 2, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(126, 'Что такое Copy Elision?', 'Оптимизация компилятора, которая убирает лишнее копирование объекта при возврате из функции или инициализации.', 1, 2, 12, 3, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(127, 'Зачем использовать ключевое слово friend?', 'Позволяет функции или другому классу получить доступ к private и protected членам текущего класса.', 1, 2, 12, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(128, 'Что делает спецификатор mutable?', 'Позволяет изменять поле класса даже внутри константных методов.', 1, 2, 12, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(129, 'Можно ли выбрасывать исключение из деструктора?', 'Крайне не рекомендуется. Если в процессе обработки одного исключения вылетит второе из деструктора, программа сразу завершится через std::terminate.', 1, 2, 12, 3, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(130, 'Для чего нужно приватное наследование?', 'Для реализации отношения \"реализован с помощью чего-то\". Все public методы базы становятся private в наследнике.', 1, 2, 12, 4, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(131, 'Что такое Curiously Recurring Template Pattern (CRTP)?', 'Паттерн, при котором класс наследуется от шаблона, используя самого себя в качестве параметра шаблона. Реализует статический полиморфизм.', 1, 2, 13, 4, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(132, 'В чем отличие using от typedef?', 'using более читаем, поддерживает шаблоны (alias templates) и лучше работает с типами функций.', 1, 2, 13, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(133, 'Что такое шаблоны вариативных аргументов (Variadic Templates)?', 'Шаблоны, которые принимают любое количество аргументов разных типов (используют синтаксис троеточия ...).', 1, 2, 13, 4, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(134, 'Разница между std::set и std::unordered_set?', 'set — это дерево (элементы отсортированы, O(log N)). unordered_set — хэш-таблица (порядок случайный, O(1) в среднем).', 1, 2, 14, 2, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(135, 'Как работает std::vector внутри?', 'Использует динамический массив. При нехватке места аллоцирует новый кусок памяти (обычно в 1.5-2 раза больше), копирует элементы и удаляет старый массив.', 1, 2, 14, 2, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(136, 'В чем особенность std::deque?', 'Двусторонняя очередь. В отличие от вектора, хранит данные в виде набора отдельных страниц (chunks), что позволяет быстро добавлять в начало без копирования всего массива.', 1, 2, 14, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(137, 'Что такое барьеры памяти (Memory Barriers)?', 'Инструкции процессора, гарантирующие определенный порядок операций с памятью, чтобы предотвратить некорректные оптимизации в многопоточности.', 1, 2, 15, 4, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(138, 'Чем std::async отличается от std::thread?', 'thread всегда создает новый поток. async может использовать пул потоков или отложить выполнение до вызова get() (deferred).', 1, 2, 15, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(139, 'Что такое lock-free алгоритмы?', 'Алгоритмы, работающие без блокировок (мьютексов), используя атомарные операции. Гарантируют прогресс хотя бы одного потока.', 1, 2, 15, 4, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(140, 'Как защитить хедер от повторного включения?', 'С помощью #ifndef HEADER_H / #define HEADER_H или современного #pragma once.', 1, 2, 16, 2, 1, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(141, 'В чем разница между статической и динамической библиотекой?', 'Статическая (.lib/.a) вшивается в exe при сборке. Динамическая (.dll/.so) загружается во время выполнения и может использоваться несколькими программами.', 1, 2, 16, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(142, 'Что делает линкер (линковщик)?', 'Собирает объектные файлы (.obj/.o) в один исполняемый файл, связывая вызовы функций с их определениями.', 1, 2, 16, 2, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(143, 'Что такое std::string_view (C++17)?', 'Легковесная обертка над строкой (указатель + длина), которая не копирует данные. Идеальна для аргументов функций только для чтения.', 1, 2, 17, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(144, 'Что такое концепты (Concepts) в C++20?', 'Позволяют накладывать ограничения на типы в шаблонах прямо в объявлении, улучшая читаемость ошибок компиляции.', 1, 2, 17, 4, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(145, 'Разница между static_cast и dynamic_cast?', 'static_cast — проверка на этапе компиляции. dynamic_cast — проверка в рантайме (только для полиморфных типов), возвращает nullptr при неудаче.', 1, 2, 17, 3, 2, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(146, 'Что такое RTTI (Run-time Type Information)?', 'Механизм, позволяющий определять тип объекта во время выполнения программы (используется в typeid и dynamic_cast).', 1, 2, 17, 3, 3, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(147, 'Что такое структурированные привязки (Structured Bindings)?', 'Фича C++17, позволяющая распаковывать кортежи или структуры в отдельные переменные: auto [x, y] = point;', 1, 2, 17, 2, 1, 0, 1, '2026-05-13 10:11:06', '2026-05-13 10:11:06'),
(148, 'Что такое \"Правило трех\", \"Правило пяти\" и \"Правило нуля\"?', 'Если классу нужен деструктор, конструктор копирования или оператор присваивания, ему нужны все три (Rule of 3). В Modern C++ добавляются конструктор и оператор перемещения (Rule of 5). Rule of 0 гласит: старайся использовать объекты, которые сами управляют ресурсами (умные указатели), чтобы не писать ничего из вышеперечисленного.', 1, 2, 12, 3, 3, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(149, 'Зачем нужен спецификатор explicit у конструктора?', 'Чтобы запретить компилятору выполнять неявное преобразование типов при инициализации или передаче аргумента в функцию.', 1, 2, 12, 2, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(150, 'Что такое делегирующий конструктор?', 'Возможность одного конструктора вызывать другой конструктор того же класса в списке инициализации (появилось в C++11).', 1, 2, 12, 2, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(151, 'Как компилятор различает перегрузку префиксного и постфиксного инкремента?', 'Постфиксный оператор принимает фиктивный параметр типа int (например: operator++(int)), чтобы отличаться от префиксного.', 1, 2, 12, 3, 3, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(152, 'В чем разница между std::vector::size() и std::vector::capacity()?', 'size — это количество реально хранящихся элементов. capacity — это количество элементов, под которые выделена память (зарезервировано).', 1, 2, 14, 2, 1, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(153, 'Разница между std::array и обычным C-массивом?', 'std::array — это тонкая обертка, которая не \"распадается\" в указатель при передаче в функцию и знает свой размер.', 1, 2, 14, 2, 1, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(154, 'Что такое функциональный объект (функтор)?', 'Объект класса, в котором перегружен оператор круглых скобок operator(). Позволяет объекту вести себя как функция, сохраняя при этом внутреннее состояние.', 1, 2, 14, 2, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(155, 'Зачем использовать std::reserve()?', 'Чтобы заранее выделить память под вектор и избежать дорогих переаллокаций при частом добавлении элементов.', 1, 2, 14, 2, 1, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(156, 'Разница между TCP и UDP?', 'TCP — гарантированная доставка, сохранение порядка, установка соединения. UDP — скорость, отсутствие гарантий, без установки соединения. Используется в играх и стриминге.', 1, 2, 16, 2, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(157, 'Что такое уровни модели OSI?', '7-уровневая модель сетевых протоколов: Физический, Канальный, Сетевой, Транспортный, Сеансовый, Представления, Прикладной.', 1, 2, 16, 2, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(158, 'Что такое сокет (Socket)?', 'Программный интерфейс (точка входа) для обеспечения обмена данными между процессами (на одной машине или через сеть).', 1, 2, 16, 2, 1, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(159, 'Что такое PID в Linux?', 'Process Identifier — уникальный номер процесса в операционной системе, по которому можно им управлять.', 1, 2, 16, 2, 1, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(160, 'Зачем нужны стандартные дескрипторы 0, 1, 2?', '0 — stdin (ввод), 1 — stdout (вывод), 2 — stderr (ошибки). Стандартные потоки данных любого процесса.', 1, 2, 16, 2, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(161, 'Что такое Pipe (Канал)?', 'Механизм межпроцессного взаимодействия (IPC), позволяющий передавать вывод одного процесса на ввод другому.', 1, 2, 16, 3, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(162, 'В чем разница между процессом и потоком (thread)?', 'Процесс — изолированная программа со своей памятью. Поток — часть процесса, потоки одного процесса делят общую память.', 1, 2, 16, 3, 1, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(163, 'Что такое корутины (Coroutines) в C++20?', 'Функции, которые могут приостанавливать выполнение и возобновлять его позже, сохраняя состояние. Используются для асинхронного кода без callback-хелла.', 1, 2, 17, 4, 3, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(164, 'Что такое концепты (Concepts)?', 'Средство наложения ограничений на параметры шаблонов на этапе компиляции, делающее ошибки в шаблонах читаемыми.', 1, 2, 17, 4, 3, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(165, 'std::variant vs std::any?', 'variant — типобезопасный \"выбор\" из заранее заданных типов. any — может хранить объект абсолютно любого типа (аналог void* с контролем типа).', 1, 2, 17, 3, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(166, 'Зачем нужен атрибут [[nodiscard]]?', 'Указывает компилятору выдавать предупреждение, если результат функции (например, код ошибки) был проигнорирован программистом.', 1, 2, 17, 3, 2, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(167, 'Что такое \"Static Initialization Order Fiasco\"?', 'Проблема, когда порядок инициализации статических объектов в разных единицах трансляции (cpp-файлах) не определен, что ведет к падениям при обращении к еще не созданным объектам.', 1, 2, 12, 4, 3, 0, 1, '2026-05-13 10:12:50', '2026-05-13 10:12:50'),
(168, 'Назовите 4 принципа ООП.', 'Инкапсуляция, Наследование, Полиморфизм и Абстракция.', 1, 3, 20, 1, 1, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(169, 'От какого класса неявно наследуются все типы в .NET?', 'От класса System.Object.', 1, 3, 20, 1, 1, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(170, 'Разрешено ли множественное наследование классов в C#?', 'Нет, класс может наследоваться только от одного родителя, но может реализовывать множество интерфейсов.', 1, 3, 20, 1, 1, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(171, 'Разница между интерфейсом и абстрактным классом?', 'Интерфейс определяет поведение (контракт), а абстрактный класс может содержать реализацию методов и состояние (поля).', 1, 3, 20, 2, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(172, 'Что такое модификатор доступа protected?', 'Член класса доступен внутри своего класса и во всех классах-наследниках.', 1, 3, 20, 2, 1, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(173, 'Разница между Value Type и Reference Type?', 'Типы значений (struct) хранятся в стеке, ссылочные типы (class) хранятся в куче, а в стеке лежит только ссылка.', 1, 3, 21, 2, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(174, 'String — это тип значения или ссылочный тип?', 'Это ссылочный тип (Reference Type), но он ведет себя как тип значения (неизменяемость, сравнение по значению).', 1, 3, 21, 2, 1, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(175, 'Что такое Boxing и Unboxing?', 'Boxing — упаковка значимого типа в объект (в кучу). Unboxing — обратное извлечение значения из объекта.', 1, 3, 21, 2, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(176, 'Разница между struct и class?', 'Struct — тип значения, не поддерживает наследование, эффективен для мелких объектов. Class — ссылочный тип, полная поддержка ООП.', 1, 3, 21, 2, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(177, 'Зачем нужно зарезервированное слово using в контексте объектов?', 'Для автоматического вызова метода Dispose() у объектов, реализующих IDisposable, чтобы освободить неуправляемые ресурсы.', 1, 3, 21, 3, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(178, 'Что такое LINQ?', 'Language Integrated Query — расширение языка для работы с данными (коллекции, БД, XML) через SQL-подобный синтаксис.', 1, 3, 22, 2, 1, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(179, 'Разница между IEnumerable и IQueryable?', 'IEnumerable выполняет запрос в памяти (подходит для коллекций). IQueryable формирует SQL-запрос и выполняет его на стороне БД.', 1, 3, 22, 3, 3, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(180, 'Что делает оператор yield?', 'Позволяет создавать итераторы (генераторы) \"на лету\", возвращая элементы коллекции по одному без создания промежуточного списка в памяти.', 1, 3, 22, 2, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(181, 'Разница между List и HashSet?', 'List — упорядоченный список (дубликаты разрешены). HashSet — неупорядоченное множество уникальных элементов (быстрый поиск O(1)).', 1, 3, 22, 2, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(182, 'Что такое CLR?', 'Common Language Runtime — виртуальная машина .NET, которая управляет памятью, потоками и выполняет JIT-компиляцию.', 1, 3, 23, 3, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(183, 'Как работает Garbage Collector (GC)?', 'Автоматически освобождает память. Разделяет объекты на 3 поколения (0, 1, 2). Чем дольше живет объект, тем в более старшее поколение он попадает.', 1, 3, 23, 3, 3, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(184, 'Что такое JIT-компиляция?', 'Just-In-Time — компиляция промежуточного кода (IL) в машинный код процессора прямо во время выполнения программы.', 1, 3, 23, 3, 3, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(185, 'Разница между Transient, Scoped и Singleton?', 'Transient — новый объект на каждый запрос. Scoped — один объект на один HTTP-запрос. Singleton — один объект на всё время жизни приложения.', 1, 3, 24, 3, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(186, 'Что такое Middleware?', 'Программные компоненты, которые выстраиваются в конвейер (pipeline) обработки HTTP-запроса и ответа.', 1, 3, 24, 3, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(187, 'Зачем нужен файл Startup.cs (или Program.cs в .NET 6+)?', 'Для настройки сервисов (DI-контейнер) и конфигурации конвейера обработки запросов (Middleware).', 1, 3, 24, 2, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(188, 'Что такое Kestrel?', 'Кроссплатформенный быстрый веб-сервер для ASP.NET Core, используемый по умолчанию.', 1, 3, 24, 3, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(189, 'async / await — как это работает?', 'await не блокирует поток, а \"отпускает\" его в пул, пока выполняется задача. Когда задача готова, выполнение возобновляется.', 1, 3, 25, 2, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(190, 'В чем разница между Task и Thread?', 'Thread — физический поток ОС (дорогой ресурс). Task — обещание работы (Promise), выполняется на потоках из ThreadPool.', 1, 3, 25, 3, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(191, 'Почему нельзя использовать async void?', 'Потому что такие методы нельзя дождаться (await), и ошибки внутри них могут привести к падению всего приложения без перехвата.', 1, 3, 25, 4, 3, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(192, 'Что делает Task.ConfigureAwait(false)?', 'Указывает задаче не возвращаться в исходный контекст синхронизации. Помогает избежать Deadlock-ов в UI и библиотеках.', 1, 3, 25, 4, 3, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(193, 'Что такое SOLID?', '5 принципов: Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, Dependency Inversion.', 1, 3, 26, 3, 3, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(194, 'Что такое Dependency Injection (DI)?', 'Паттерн, при котором зависимости объекта предоставляются ему извне, а не создаются им самим. Упрощает тестирование и замену модулей.', 1, 3, 26, 3, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(195, 'Слабосвязанный код (Loose Coupling) — зачем он?', 'Для того чтобы изменения в одном модуле не ломали другие. Достигается через использование интерфейсов и DI.', 1, 3, 26, 4, 3, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(196, 'Что такое Circuit Breaker?', 'Паттерн \"Предохранитель\": если микросервис не отвечает, запросы к нему временно прекращаются, чтобы не перегружать систему.', 1, 3, 27, 4, 3, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(197, 'Разница между монолитом и микросервисами?', 'Монолит — всё в одном приложении. Микросервисы — разделение на независимые сервисы, общающиеся по сети (HTTP, gRPC, RabbitMQ).', 1, 3, 27, 3, 2, 0, 1, '2026-05-13 10:14:52', '2026-05-13 10:14:52'),
(198, 'В чем разница между ключевыми словами new и override при переопределении?', 'override переопределяет виртуальный метод базового класса (полиморфизм). new скрывает метод базового класса (shadowing), разрывая связь с полиморфизмом.', 1, 3, 20, 2, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(199, 'Что такое Sealed-класс?', 'Класс с модификатором sealed нельзя наследовать. Это полезно для безопасности и небольшой оптимизации производительности.', 1, 3, 20, 2, 1, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(200, 'Разница между const и readonly?', 'const — значение подставляется на этапе компиляции. readonly — значение можно задать в конструкторе во время выполнения программы.', 1, 3, 20, 2, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(201, 'Что такое индексатор (Indexer) в C#?', 'Специальный метод, позволяющий обращаться к объекту класса как к массиву, используя квадратные скобки [index].', 1, 3, 20, 2, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(202, 'Что такое Large Object Heap (LOH)?', 'Специальная область кучи для объектов больше 85 000 байт. Она не сжимается (не дефрагментируется) по умолчанию, что может привести к нехватке памяти.', 1, 3, 21, 4, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(203, 'Как работает интернирование строк (String Interning)?', 'CLR хранит таблицу уникальных строковых констант. Если две переменные содержат одинаковый текст-литерал, они будут ссылаться на один объект в памяти.', 1, 3, 21, 3, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(204, 'Может ли экземпляр структуры храниться в куче (heap)?', 'Да, если структура является полем класса или если произошел Boxing (упаковка в объект).', 1, 3, 21, 3, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(205, 'Что такое immutable object (неизменяемый объект)?', 'Объект, состояние которого нельзя изменить после создания. Примеры: String, и пользовательские классы с полями init или readonly.', 1, 3, 21, 3, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(206, 'В чем разница между отложенным (Deferred) и немедленным исполнением в LINQ?', 'Deferred (Select, Where) выполняется только при итерации (foreach). Немедленное (ToList, Count) выполняет запрос к данным мгновенно.', 1, 3, 22, 3, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(207, 'Как работает Dictionary внутри?', 'На основе хэш-таблицы. Использует GetHashCode() ключа для поиска бакета. При коллизиях использует связные списки внутри бакетов.', 1, 3, 22, 3, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(208, 'Разница между IEnumerable и IList?', 'IEnumerable — только для чтения и перебора. IList поддерживает изменение коллекции, вставку и удаление элементов по индексу.', 1, 3, 22, 2, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(209, 'Что такое рефлексия (Reflection)?', 'Механизм, позволяющий во время выполнения получать информацию о типах, методах, атрибутах и динамически вызывать код.', 1, 3, 23, 4, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(210, 'Зачем нужно три поколения (0, 1, 2) в Garbage Collector?', 'Гипотеза поколений: большинство объектов умирает молодыми. Проверять 0 поколение быстро, что делает паузы приложения минимальными.', 1, 3, 23, 4, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(211, 'Что такое управляемый (Managed) и неуправляемый код?', 'Managed код исполняется под контролем CLR (память, безопасность). Unmanaged (C++, Win32 API) работает напрямую с ОС и памятью.', 1, 3, 23, 4, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(212, 'Что такое Action Filters?', 'Атрибуты, которые позволяют выполнять код до или после выполнения метода контроллера (логирование, кэширование).', 1, 3, 24, 3, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(213, 'Разница между Web API и MVC в контексте ASP.NET Core?', 'В .NET Core это один фреймворк. MVC обычно возвращает View (HTML), Web API возвращает данные (JSON/XML).', 1, 3, 24, 2, 1, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(214, 'Как включить CORS в ASP.NET Core?', 'Через services.AddCors() в DI и app.UseCors() в конвейере Middleware.', 1, 3, 24, 3, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(215, 'Что делает ключевое слово lock?', 'Гарантирует, что только один поток может войти в критическую секцию кода, используя объект-заглушку.', 1, 3, 25, 3, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(216, 'Зачем нужен ThreadPool?', 'Для экономии ресурсов ОС. Вместо создания нового потока под каждую задачу, задача берется из очереди и выполняется свободным потоком из пула.', 1, 3, 25, 3, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(217, 'Разница между асинхронностью и параллелизмом?', 'Асинхронность — способ не блокировать поток во время ожидания (I/O). Параллелизм — одновременное выполнение нескольких задач на разных ядрах CPU.', 1, 3, 25, 3, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(218, 'Что такое Cohesion (Связность) и Coupling (Связанность)?', 'Хороший дизайн — это High Cohesion (модуль делает одну задачу) и Low Coupling (модули минимально зависят друг от друга).', 1, 3, 26, 4, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(219, 'Что такое Dependency Inversion (D из SOLID)?', 'Принцип: зависимости должны строиться на абстракциях (интерфейсах), а не на конкретных классах реализаций.', 1, 3, 26, 4, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52');
INSERT INTO `questions` (`id`, `question`, `explanation`, `route_id`, `language_id`, `topic_id`, `experience_level_id`, `difficulty`, `multiple_answers`, `is_active`, `created_at`, `updated_at`) VALUES
(220, 'Что такое Идемпотентность в API?', 'Свойство метода: повторный вызов с теми же данными не меняет состояние системы более одного раза (важно для оплаты или создания заказов).', 1, 3, 27, 4, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(221, 'Что такое Docker Multi-stage build?', 'Процесс сборки образа в несколько этапов: в первом компилируем код, во второй копируем только готовый бинарник, уменьшая размер итогового образа.', 1, 3, 27, 4, 2, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(222, 'Зачем нужны брокеры сообщений (RabbitMQ/Kafka)?', 'Для асинхронного общения между микросервисами, обеспечения отказоустойчивости и масштабируемости системы.', 1, 3, 27, 4, 3, 0, 1, '2026-05-13 10:15:52', '2026-05-13 10:15:52'),
(223, 'Какие типы данных существуют в JS?', '7 примитивных типов: string, number, boolean, null, undefined, symbol, bigint. И один сложный тип — object.', 2, 4, 30, 1, 1, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(224, 'В чем разница между var, let и const?', 'var имеет функциональную область видимости и подвержен всплытию. let и const имеют блочную область видимости. const запрещает переопределение ссылки.', 2, 4, 30, 1, 1, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(225, 'Что такое \"use strict\"?', 'Директива, включающая строгий режим выполнения кода. Она исправляет ошибки движка и запрещает потенциально опасные конструкции.', 2, 4, 30, 2, 1, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(226, 'Почему typeof null возвращает \"object\"?', 'Это официально признанная ошибка в первой реализации JS, которую решили не исправлять ради обратной совместимости.', 2, 4, 30, 3, 2, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(227, 'Разница между == и ===?', '== выполняет неявное приведение типов перед сравнением. === сравнивает и значения, и типы (строгое равенство).', 2, 4, 30, 1, 1, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(228, 'Что такое замыкание (closure)?', 'Способность функции запоминать свою внешнюю область видимости, в которой она была создана, даже после выхода из неё.', 2, 4, 31, 2, 2, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(229, 'Разница между Function Declaration и Function Expression?', 'Declaration всплывает (можно вызвать до объявления). Expression создается только когда поток выполнения доходит до него.', 2, 4, 31, 2, 1, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(230, 'Что такое стрелочные функции?', 'Короткий синтаксис функций. Особенности: не имеют своего \"this\", \"arguments\" и не могут быть конструкторами.', 2, 4, 31, 2, 2, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(231, 'Разница между call, apply и bind?', 'call и apply вызывают функцию мгновенно (call принимает список аргументов, apply — массив). bind возвращает новую функцию с привязанным контекстом.', 2, 4, 31, 3, 2, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(232, 'Что такое поднятие (Hoisting)?', 'Механизм в JS, при котором объявления переменных и функций перемещаются в начало их области видимости перед выполнением кода.', 2, 4, 31, 2, 2, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(233, 'Что такое Event Loop?', 'Механизм, позволяющий JS выполнять неблокирующие операции ввода-вывода, переключаясь между очередью задач (Task Queue) и стеком вызовов.', 2, 4, 33, 3, 3, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(234, 'Разница между микрозадачами и макрозадачами?', 'Микрозадачи (Promises, MutationObserver) имеют приоритет и выполняются сразу после текущего кода, до следующей макрозадачи (setTimeout, DOM события).', 2, 4, 33, 4, 3, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(235, 'Что такое Promise?', 'Объект, представляющий результат успешного или неудачного завершения асинхронной операции.', 2, 4, 33, 2, 2, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(237, 'Что такое всплытие (Bubbling) событий?', 'При наступлении события обработчики сначала срабатывают на самом глубоком элементе, а затем поднимаются вверх по дереву к родителям.', 2, 4, 34, 2, 1, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(239, 'Что такое CORS?', 'Cross-Origin Resource Sharing — механизм безопасности браузера, который ограничивает запросы между разными доменами.', 2, 4, 34, 3, 2, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(240, 'LocalStorage vs SessionStorage?', 'LocalStorage хранит данные вечно (пока не удалит юзер). SessionStorage — только пока открыта вкладка браузера.', 2, 4, 34, 2, 1, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(241, 'Почему Node.js однопоточный?', 'Движок V8 выполняет JS в одном потоке, но асинхронные операции (сеть, файлы) выполняются пулом потоков системной библиотеки libuv.', 1, 4, 35, 3, 3, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(242, 'Что такое Streams в Node.js?', 'Интерфейс для работы с потоковыми данными (чтение/запись по кусочкам), что критично для обработки огромных файлов без переполнения памяти.', 1, 4, 35, 3, 3, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(243, 'Разница между setImmediate() и setTimeout(0)?', 'setTimeout попадает в очередь макрозадач (таймеров), а setImmediate выполняется сразу после завершения текущей фазы I/O событий.', 1, 4, 35, 4, 3, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(244, 'Что такое Webpack?', 'Мощный сборщик модулей, который превращает тысячи JS/CSS файлов и картинок в один или несколько оптимизированных бандлов.', 2, 4, 36, 2, 2, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(245, 'Зачем нужен package-lock.json?', 'Фиксирует точные версии всех зависимостей, чтобы проект собирался одинаково на всех компьютерах разработчиков.', 2, 4, 36, 2, 1, 0, 1, '2026-05-13 10:18:12', '2026-05-13 10:18:12'),
(246, 'Что такое прототипное наследование?', 'Механизм, при котором объекты могут наследовать свойства и методы других объектов через скрытую ссылку [[Prototype]]. Это основа наследования в JS.', 2, 4, 32, 2, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(247, 'Разница между Map и обычным Object?', 'Map сохраняет порядок вставки, позволяет использовать любые типы в качестве ключей и имеет встроенное свойство size.', 2, 4, 32, 2, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(248, 'Deep copy vs Shallow copy?', 'Поверхностная копия копирует только ссылки на вложенные объекты. Глубокая копия создает полностью независимый дубликат всех вложенных структур.', 2, 4, 32, 3, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(249, 'Зачем нужен конструктор Proxy?', 'Позволяет перехватывать и переопределять основные операции с объектом (чтение свойств, запись, вызов функций).', 2, 4, 32, 4, 3, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(250, 'Что такое дескрипторы свойств?', 'Объекты конфигурации атрибутов поля (writable, enumerable, configurable). Позволяют сделать свойство неизменяемым или скрытым.', 2, 4, 32, 3, 3, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(251, 'Разница между async и defer в подключении скриптов?', 'async загружает и выполняет скрипт сразу (блокируя парсинг HTML). defer загружает в фоне и выполняет только после полной отрисовки DOM.', 2, 4, 34, 2, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(252, 'Что такое Web Workers?', 'Механизм запуска JS-кода в фоновом потоке отдельно от основного (UI) потока, чтобы тяжелые вычисления не \"вешали\" интерфейс.', 2, 4, 34, 3, 3, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(253, 'Разница между innerHTML и innerText?', 'innerHTML парсит строку как HTML-код. innerText работает только с текстом, игнорируя или экранируя теги.', 2, 4, 34, 1, 1, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(254, 'Что такое Virtual DOM?', 'Легковесная копия реального DOM в памяти. Фреймворки (React) используют её для вычисления минимальных изменений перед обновлением реального дерева.', 2, 4, 34, 2, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(255, 'Что такое Middleware в Express.js?', 'Функции, имеющие доступ к объектам запроса (req) и ответа (res), которые могут изменять их или завершать цикл запроса.', 1, 4, 35, 2, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(256, 'Что такое Token-based authentication?', 'Метод авторизации (например JWT), при котором сервер выдает клиенту подписанный ключ. Клиент шлет его в заголовках, а сервер проверяет подпись без запроса к БД.', 1, 4, 35, 3, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(257, 'Разница между fork() и spawn() в Node.js?', 'spawn запускает процесс и передает данные потоками (stream). fork создает отдельный экземпляр V8 для выполнения JS-кода в новом потоке.', 1, 4, 35, 4, 3, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(258, 'Что такое XSS (Cross-Site Scripting)?', 'Уязвимость, при которой злоумышленник внедряет вредоносный JS-код в страницу, который затем исполняется у других пользователей.', 2, 4, 36, 2, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(259, 'Как защититься от SQL-инъекций в JS?', 'Никогда не склеивать строки запроса вручную. Всегда использовать подготовленные выражения (prepared statements) и плейсхолдеры.', 1, 4, 36, 3, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(260, 'Принципы SOLID в JavaScript?', 'Набор из 5 правил проектирования (SRP, OCP, LSP, ISP, DIP), направленных на создание гибкой и поддерживаемой архитектуры приложений.', 2, 4, 36, 4, 3, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(261, 'Что такое Temporal Dead Zone (TDZ)?', 'Период от начала выполнения области видимости до момента объявления переменной через let или const, когда обращение к ней вызывает ошибку.', 2, 4, 30, 3, 3, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(262, 'Что такое IIFE?', 'Immediately Invoked Function Expression — функция, которая выполняется сразу после того, как она была определена.', 2, 4, 31, 2, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(264, 'Что такое мемоизация?', 'Техника оптимизации: сохранение результата выполнения функции для предотвращения повторных вычислений при тех же входных данных.', 2, 4, 31, 3, 2, 0, 1, '2026-05-13 10:19:08', '2026-05-13 10:19:08'),
(265, 'Что такое Symbol и зачем он нужен?', 'Уникальный и неизменяемый тип данных, используемый в качестве идентификаторов для свойств объектов, чтобы избежать конфликтов имен.', 2, 4, 30, 2, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(266, 'Что такое BigInt?', 'Специальный тип данных для работы с целыми числами произвольной точности, которые больше максимально допустимого значения Number (2^53 - 1).', 2, 4, 30, 2, 1, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(267, 'Как работает оператор нулевого слияния (??)?', 'Возвращает правый операнд, только если левый равен null или undefined. В отличие от ||, он считает 0 и \"\" валидными значениями.', 2, 4, 30, 2, 1, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(268, 'Что такое битовые операторы в JS?', 'Операторы (&, |, ^, ~), которые работают с числами на уровне их двоичного представления (32-битные целые числа).', 2, 4, 30, 3, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(269, 'Что такое генераторы (function*)?', 'Функции, которые могут приостанавливать свое выполнение (yield) и возобновлять его позже, возвращая итератор.', 2, 4, 31, 3, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(270, 'Разница между рекурсией и итерацией?', 'Рекурсия вызывает функцию саму себя (риск переполнения стека), итерация использует циклы. Итерация обычно эффективнее по памяти в JS.', 2, 4, 31, 2, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(271, 'Зачем нужен метод bind()?', 'Создает новую функцию, которая при вызове устанавливает указанный \"this\" и предопределенные аргументы.', 2, 4, 31, 2, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(272, 'В чем особенность WeakMap и WeakSet?', 'Они не препятствуют сборщику мусора удалять объекты-ключи, если на них больше нет других ссылок. Это предотвращает утечки памяти.', 2, 4, 32, 4, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(273, 'Разница между Object.freeze() и Object.seal()?', 'freeze делает объект полностью неизменяемым. seal запрещает добавлять/удалять свойства, но позволяет изменять значения существующих.', 2, 4, 32, 3, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(274, 'Как проверить, что свойство принадлежит самому объекту, а не прототипу?', 'С помощью метода obj.hasOwnProperty(\"prop\") или статического Object.hasOwn(obj, \"prop\").', 2, 4, 32, 2, 1, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(275, 'Promise.all vs Promise.allSettled?', 'all падает, если хотя бы один промис отклонен. allSettled всегда ждет завершения всех и возвращает массив с результатами и статусами.', 2, 4, 33, 3, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(276, 'Что такое Promise.race()?', 'Возвращает результат первого выполнившегося (успешно или с ошибкой) промиса из списка.', 2, 4, 33, 3, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(277, 'Что такое AbortController?', 'Объект, позволяющий отменять асинхронные задачи (например, запросы fetch), когда они больше не нужны.', 2, 4, 33, 3, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(278, 'Что такое делегирование событий?', 'Прием, когда один обработчик на родителе следит за событиями на всех своих потомках благодаря всплытию (Bubbling).', 2, 4, 34, 2, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(279, 'Что такое Shadow DOM?', 'Механизм инкапсуляции разметки и стилей внутри веб-компонента, изолирующий их от основного DOM документа.', 2, 4, 34, 4, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(280, 'Зачем нужен requestAnimationFrame()?', 'Метод для плавной анимации: он просит браузер вызвать функцию перед следующей перерисовкой экрана (обычно 60 раз в секунду).', 2, 4, 34, 3, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(281, 'Разница между cookie и sessionStorage?', 'Cookie шлются на сервер с каждым запросом (макс 4КБ). sessionStorage живет только в браузере и только в рамках одной вкладки (макс 5МБ+).', 2, 4, 34, 2, 1, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(282, 'Что такое Buffer в Node.js?', 'Объект для работы с \"сырыми\" бинарными данными вне памяти V8. Необходим для работы с файлами и сетевыми пакетами.', 1, 4, 35, 3, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(283, 'ES Modules (import) vs CommonJS (require)?', 'CJS синхронный и динамический. ESM асинхронный, статический (поддерживает Tree Shaking) и является современным стандартом.', 1, 4, 35, 3, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(284, 'Зачем нужен модуль Cluster в Node.js?', 'Позволяет запускать дочерние процессы, которые делят один порт сервера, чтобы использовать все ядра процессора на полную мощность.', 1, 4, 35, 4, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(285, 'Что такое Tree Shaking?', 'Процесс удаления неиспользуемого (\"мертвого\") кода из итогового бандла при сборке (например, через Webpack или Rollup).', 2, 4, 36, 3, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(286, 'Что такое Content Security Policy (CSP)?', 'Заголовок безопасности, который указывает браузеру, из каких источников можно загружать скрипты, стили и картинки. Основная защита от XSS.', 2, 4, 36, 4, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(287, 'Что такое CSRF-атака?', 'Подделка межсайтового запроса: когда злонамеренный сайт заставляет браузер пользователя выполнить действие на другом сайте, где он авторизован.', 1, 4, 36, 3, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(288, 'Разница между Unit и Integration тестами?', 'Unit тестирует одну функцию в изоляции. Integration — взаимодействие нескольких модулей (например, API + База данных).', 2, 4, 36, 2, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(289, 'Как работает Garbage Collector в V8?', 'Использует алгоритм Mark-and-Sweep (пометить и очистить) и разделяет объекты на \"молодое\" и \"старое\" поколения для оптимизации.', 2, 4, 30, 4, 3, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(290, 'Что такое утечка памяти в JavaScript?', 'Ситуация, когда объекты в памяти больше не используются, но ссылки на них остаются (например, забытые глобальные переменные или таймеры).', 2, 4, 30, 3, 2, 0, 1, '2026-05-13 10:21:04', '2026-05-13 10:21:04'),
(291, 'Что такое HTML?', 'HyperText Markup Language — язык разметки, определяющий структуру веб-страницы с помощью иерархии тегов и атрибутов.', 2, 5, 40, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(292, 'Что такое DOCTYPE?', 'Это объявление версии HTML. Оно нужно браузеру, чтобы правильно интерпретировать и отображать содержимое страницы.', 2, 5, 40, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(293, 'Разница между блочными и строчными элементами?', 'Блочные (div, p) занимают всю ширину и начинаются с новой строки. Строчные (span, a) занимают место только под контент и не создают переносов.', 2, 5, 40, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(295, 'Что такое валидный HTML?', 'Код, написанный строго по спецификации W3C без ошибок в структуре, вложенности и атрибутах. Важен для SEO и корректного рендеринга.', 2, 5, 40, 2, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(296, 'Тег для создания ссылок и его атрибуты?', 'Тег <a>. Основные атрибуты: href (URL), title (подсказка), target (где открыть ссылку, например _blank).', 2, 5, 41, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(297, 'Виды списков в HTML?', '<ul> — маркированный (неупорядоченный), <ol> — нумерованный (упорядоченный). Внутри обоих используется <li>.', 2, 5, 41, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(298, 'Зачем нужен атрибут alt у изображений?', 'Для описания картинки. Помогает SEO и скринридерам для слабовидящих. Отображается, если картинка не загрузилась.', 2, 5, 41, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(300, 'Можно ли использовать несколько классов для одного элемента?', 'Да, через пробел: <div class=\"box active primary\">. Это позволяет комбинировать стили.', 2, 5, 41, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(301, 'Что такое Image Map?', 'Тег <map> в связке с <area>, позволяющий создать на одном изображении несколько кликабельных зон с разными ссылками.', 2, 5, 41, 3, 2, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(302, 'Основные теги для создания форм?', '<form> (контейнер), <input> (поле ввода), <textarea> (текст), <select> (выпадающий список), <button> (кнопка).', 2, 5, 42, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(303, 'GET vs POST в формах?', 'GET добавляет данные в URL (виден пользователю, лимит по длине). POST передает данные в теле запроса (скрыто, для больших данных).', 2, 5, 42, 2, 2, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(304, 'Разница между type=\"text\" и type=\"submit\"?', 'text создает поле для ввода символов. submit создает кнопку, которая отправляет данные формы на сервер.', 2, 5, 42, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(305, 'Зачем нужен тег <label> и атрибут for?', 'Связывает текстовую подпись с полем ввода. При клике на label фокус автоматически переходит в связанный инпут.', 2, 5, 42, 2, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(306, 'Что такое семантическая верстка?', 'Использование тегов по их смыслу (header, footer, main, section, article), а не просто div для всего. Улучшает доступность и SEO.', 2, 5, 43, 2, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(307, 'Разница между <strong> и <b>?', '<b> просто делает текст жирным визуально. <strong> помечает текст как важный для поисковиков и скринридеров.', 2, 5, 43, 2, 2, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(308, 'Сколько тегов <main> может быть на странице?', 'Только один. Если их больше, браузер проигнорирует все, кроме первого.', 2, 5, 43, 3, 3, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(309, 'Зачем нужны теги <section> и <article>?', 'section для логического деления страницы. article для самостоятельного, завершенного куска контента (новости, пост в блоге).', 2, 5, 43, 2, 2, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(310, 'Что такое метатеги?', 'Элементы <meta> внутри <head>, описывающие данные о странице: кодировку, описание (description), ключевые слова, вьюпорт.', 2, 5, 44, 2, 2, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(311, 'Атрибуты тега <video>?', 'src (путь), controls (пульт управления), autoplay (автостарт), loop (повтор), muted (без звука).', 2, 5, 44, 2, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(312, 'Что делает <meta name=\"viewport\">?', 'Управляет отображением страницы на мобильных устройствах, масштабируя контент под ширину экрана.', 2, 5, 44, 2, 2, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(313, 'Что такое элемент <canvas>?', 'Область на странице, в которой можно рисовать графику (2D или 3D) на лету с помощью JavaScript.', 2, 5, 44, 3, 2, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(314, 'Как создать ссылку на якорь внутри страницы?', 'Дать целевому элементу id=\"name\", а в ссылке указать <a href=\"#name\">.', 2, 5, 41, 1, 1, 0, 1, '2026-05-13 10:25:44', '2026-05-13 10:25:44'),
(315, 'Разница между атрибутами id и class?', 'id — уникальный идентификатор (может быть только один на странице). class — групповой идентификатор, может применяться к множеству элементов одновременно.', 2, 5, 40, 1, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(316, 'Что такое HTML-сущности (entities) и как вывести знак копирайта?', 'Спецсимволы, которые нельзя ввести просто так. Знак копирайта © выводится кодом &copy; или &#169;.', 2, 5, 40, 1, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(317, 'Что такое комментарии в HTML и как их писать?', 'Код, который игнорируется браузером. Пишется так: <!-- Ваш комментарий -->. Полезен для пояснений в разметке.', 2, 5, 40, 1, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(318, 'Зачем нужен глобальный атрибут lang у тега html?', 'Указывает язык контента. Важен для систем синтеза речи (скринридеров) и правильного переноса слов браузером.', 2, 5, 40, 2, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(319, 'Разница между тегами <button> и <input type=\"button\">?', '<button> может содержать внутри себя другие теги (текст + картинка), а <input> принимает значение только текстом через атрибут value.', 2, 5, 41, 2, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(320, 'Что делает тег <br> и есть ли у него пара?', 'Создает принудительный перенос строки. Это одиночный тег, закрывающая пара ему не нужна.', 2, 5, 41, 1, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(321, 'Разница между тегами <ul>, <ol> и <dl>?', 'ul — маркированный список, ol — нумерованный, dl — список определений (термин <dt> и описание <dd>).', 2, 5, 41, 2, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(322, 'Что такое тег <iframe>?', 'Позволяет встроить одну HTML-страницу внутрь другой. Часто используется для карт, видео с YouTube или виджетов.', 2, 5, 44, 2, 2, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(323, 'Зачем нужен тег <figure> и <figcaption>?', 'Для группировки контента (картинка, график, код) и добавления к нему подписи, которая семантически связана с этим контентом.', 2, 5, 41, 2, 2, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(324, 'Что такое атрибут placeholder?', 'Текст-подсказка внутри поля ввода, который исчезает, когда пользователь начинает вводить данные.', 2, 5, 42, 1, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(325, 'Зачем нужны атрибуты readonly и disabled?', 'readonly запрещает менять текст, но данные отправляются. disabled полностью отключает поле, и оно не участвует в отправке формы.', 2, 5, 42, 2, 2, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(326, 'Что такое тег <datalist>?', 'Позволяет создать список предустановленных вариантов для тега <input>. Работает как автодополнение (autocomplete).', 2, 5, 42, 2, 2, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(327, 'Разница между тегами <progress> и <meter>?', 'progress для отображения хода задачи (загрузка файла). meter для статических измерений в диапазоне (заполненность диска, сила пароля).', 2, 5, 42, 3, 2, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(328, 'Что делает атрибут required?', 'Указывает браузеру, что поле обязательно для заполнения перед отправкой формы.', 2, 5, 42, 1, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(329, 'Что такое ARIA-роли (role=\"...\")?', 'Атрибуты для улучшения доступности. Они объясняют скринридерам смысл элементов, если стандартных тегов недостаточно (например, role=\"button\" на div).', 2, 5, 43, 3, 3, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(330, 'Разница между тегами <time> и простым текстом?', 'Тег <time> позволяет машинам (календарям, поисковикам) понимать дату и время в машиночитаемом формате через атрибут datetime.', 2, 5, 43, 2, 2, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(331, 'Зачем нужен тег <nav>?', 'Определяет блок навигации. Помогает поисковикам и людям с ограниченными возможностями быстрее находить меню сайта.', 2, 5, 43, 2, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(332, 'Что такое \"Схлопывание границ\" в контексте чистого HTML?', 'В HTML/CSS вертикальные отступы (margins) соседних блоков могут объединяться в один. Это нюанс блочной модели.', 2, 5, 40, 3, 2, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(333, 'Что такое атрибуты async и defer для тега <script>?', 'async загружает и выполняет скрипт сразу. defer загружает в фоне и выполняет только после того, как весь HTML распарсен.', 2, 5, 44, 3, 3, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(334, 'Разница между <link rel=\"preload\"> и \"prefetch\"?', 'preload — высокий приоритет для текущей страницы. prefetch — низкий приоритет для ресурсов, которые понадобятся на следующей странице.', 2, 5, 44, 4, 3, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(335, 'Зачем нужен тег <noscript>?', 'Для вывода контента пользователям, у которых в браузере отключен JavaScript или он не поддерживается.', 2, 5, 44, 2, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(336, 'Что такое атрибут rel=\"noopener\" у ссылок?', 'Защита безопасности. Запрещает открываемой странице получать доступ к объекту window.opener исходной страницы.', 2, 5, 44, 4, 3, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(337, 'Что такое фавиконка (favicon) и как её подключить?', 'Маленькая иконка сайта во вкладке браузера. Подключается через <link rel=\"icon\" href=\"path/to/icon.svg\">.', 2, 5, 44, 1, 1, 0, 1, '2026-05-13 10:26:45', '2026-05-13 10:26:45'),
(438, 'Как работает специфичность (вес) селекторов?', 'Это алгоритм расчета приоритета. Вес распределяется так: Inline стиль (1000) > ID (100) > Class/Pseudo-class (10) > Tag (1). !important перебивает всё.', 2, 6, 50, 2, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(439, 'Разница между :first-child и :first-of-type?', 'first-child выбирает элемент, если он является ПЕРВЫМ ребенком родителя. first-of-type выбирает ПЕРВЫЙ элемент конкретного ТИПА среди детей.', 2, 6, 50, 3, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(440, 'Как работает псевдокласс :not()?', 'Позволяет выбрать все элементы, КРОМЕ тех, что соответствуют селектору в скобках. Например, li:not(.active).', 2, 6, 50, 2, 1, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(441, 'Что такое БЭМ?', 'Методология именования: Блок__Элемент--Модификатор. Помогает избежать каскада и делает стили независимыми и переиспользуемыми.', 2, 6, 50, 2, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(442, 'Как работает псевдокласс :placeholder-shown?', 'Он активен, пока в инпуте виден текст подсказки (placeholder). Как только пользователь начинает вводить текст — псевдокласс перестает работать.', 2, 6, 50, 3, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(443, 'Разница между border-box и content-box?', 'В content-box (дефолт) padding и border добавляются К ширине. В border-box они включаются В ширину, не раздувая блок.', 2, 6, 51, 1, 1, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(444, 'Разница между position: absolute и fixed?', 'Absolute позиционируется относительно ближайшего родителя с position отличным от static. Fixed — всегда относительно окна браузера.', 2, 6, 51, 2, 1, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(445, 'Что такое \"Схлопывание границ\" (Margin Collapsing)?', 'Вертикальные отступы (margin) соседних блоков объединяются в один, равный большему из них. Не работает для flex/grid и абсолютов.', 2, 6, 51, 3, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(446, 'Как работает z-index и контекст наложения?', 'Определяет порядок элементов по оси Z. Работает только для позиционированных элементов. Новый контекст наложения (opacity < 1, transform) может изолировать z-index внутри.', 2, 6, 51, 3, 3, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(447, 'Flexbox vs CSS Grid — что и когда?', 'Flexbox одномерный (либо ряд, либо колонка), идеален для мелких компонентов. Grid двумерный (ряды + колонки), идеален для макета всей страницы.', 2, 6, 52, 2, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(448, 'Что такое flex-basis?', 'Определяет начальный размер элемента до распределения свободного пространства. Имеет приоритет над width в flex-контейнере.', 2, 6, 52, 3, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(449, 'Как выровнять элемент по центру в Grid?', 'display: grid; place-items: center; — это самый короткий способ выравнивания по обеим осям.', 2, 6, 52, 2, 1, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(450, 'Разница между em и rem?', 'rem зависит только от font-size корневого элемента (html). em зависит от font-size текущего или родительского элемента.', 2, 6, 53, 2, 1, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(451, 'Зачем нужны Media Queries?', 'Позволяют применять стили в зависимости от характеристик устройства: ширины экрана, ориентации или разрешения.', 2, 6, 53, 2, 1, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(452, 'Transform vs Top/Left для анимации?', 'Transform выполняется на GPU (композитный слой), не вызывая перерисовку всей страницы (Reflow). Top/Left нагружают CPU и тормозят.', 2, 6, 54, 3, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(453, 'Что такое will-change?', 'Подсказка браузеру заранее подготовить ресурсы для анимации элемента, вынося его на отдельный слой GPU.', 2, 6, 54, 4, 3, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(454, 'Что такое Критический путь рендеринга (CRP)?', 'Последовательность шагов браузера: DOM + CSSOM -> Render Tree -> Layout -> Paint. CSS блокирует рендеринг, пока не загрузится полностью.', 2, 6, 55, 4, 3, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(455, 'Reflow vs Repaint?', 'Reflow (Layout) — пересчет геометрии всех элементов. Repaint — перекраска пикселей (цвет, тень). Reflow гораздо дороже для производительности.', 2, 6, 55, 4, 3, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(456, 'Преимущества CSS-препроцессоров (Sass/Less)?', 'Переменные, вложенность, миксины (функции), математические операции и разбиение кода на модули.', 2, 6, 55, 3, 1, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(457, 'Каков будет display у span внутри flex-родителя?', 'Элемент span (строчный по дефолту) автоматически становится блочным (flex-item), и свойства вроде width/height начнут работать.', 2, 6, 52, 3, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(458, 'padding в em при font-size: 16px. Как получить 8px?', 'Нужно задать padding: 0.5em. Так как 0.5 * 16 = 8.', 2, 6, 53, 2, 1, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(459, 'Что будет, если в константном объекте поменять цвет фона через currentColor?', 'Если фон дочернего элемента задан как background-color: currentColor, он всегда будет автоматически меняться при изменении свойства color родителя.', 2, 6, 54, 3, 2, 0, 1, '2026-05-13 10:36:30', '2026-05-13 10:36:30'),
(460, 'Разница между селекторами :is() и :where()?', 'Оба позволяют группировать селекторы. Главное отличие: :is() берет специфичность самого сильного селектора в списке, а :where() всегда имеет специфичность 0.', 2, 6, 50, 3, 3, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(461, 'Что такое \"родительский селектор\" :has()?', 'Революционный псевдокласс (2023+), позволяющий стилизовать родителя в зависимости от наличия в нем определенных детей или их состояний.', 2, 6, 50, 4, 3, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(462, 'Как работают комбинаторы соседства (+ и ~)?', '+ выбирает только ПЕРВЫЙ следующий соседний элемент. ~ выбирает ВСЕ последующие соседние элементы того же уровня.', 2, 6, 50, 2, 1, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(463, 'Что такое селекторы атрибутов?', 'Позволяют выбирать элементы по наличию или значению атрибутов, например: a[href^=\"https\"] выберет все ссылки, начинающиеся на https.', 2, 6, 50, 2, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(464, 'Зачем нужны CSS Resets или Normalize.css?', 'Браузеры имеют разные дефолтные отступы. Reset полностью их обнуляет, а Normalize приводит к единому стандарту, сохраняя полезные умолчания.', 2, 6, 51, 2, 1, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(465, 'Что такое Stacking Context (Контекст наложения)?', 'Слой в памяти браузера, внутри которого элементы упорядочиваются по z-index. Создается через position: fixed, opacity < 1 или transform.', 2, 6, 51, 3, 3, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(466, 'Разница между visibility: hidden и display: none?', 'display: none полностью убирает элемент из верстки (место не занимает). visibility: hidden скрывает элемент, но сохраняет его физическое место в макете.', 2, 6, 51, 2, 1, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(467, 'Как реализовать эффект Sticky Header?', 'С помощью position: sticky; top: 0;. Элемент будет вести себя как relative, пока не \"прилипнет\" к краю экрана при скролле.', 2, 6, 51, 2, 1, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(468, 'Разница между align-items и align-content во флексах?', 'align-items выравнивает элементы ВНУТРИ одной строки. align-content выравнивает сами СТРОКИ в многострочном флекс-контейнере.', 2, 6, 52, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(469, 'Что такое CSS Container Queries?', 'Новая технология (вместо Media Queries), позволяющая стилизовать элемент в зависимости от размера его РОДИТЕЛЬСКОГО контейнера, а не всего экрана.', 2, 6, 52, 4, 3, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(470, 'Свойство aspect-ratio — зачем оно?', 'Позволяет жестко задать пропорции блока (например, 16/9), которые будут сохраняться автоматически при изменении ширины.', 2, 6, 52, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(471, 'Что такое Grid Template Areas?', 'Способ описания сетки \"словами\", где вы буквально рисуете макет буквами в CSS, а потом привязываете к ним элементы.', 2, 6, 52, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(472, 'Единицы измерения ch и ex?', 'ch равна ширине символа \"0\" текущего шрифта. ex равна высоте строчной буквы \"x\". Полезно для ограничения ширины текстовых блоков.', 2, 6, 53, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(473, 'Что такое сглаживание шрифтов (Font Smoothing)?', 'Свойства типа -webkit-font-smoothing позволяют сделать шрифт на Mac/iOS более тонким и четким, убирая лишнюю жирность.', 2, 6, 53, 3, 3, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(474, 'Разница между vmin и vmax?', 'vmin берет минимальное значение из ширины или высоты вьюпорта. vmax — максимальное. Идеально для масштабирования текста на мобилках.', 2, 6, 53, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(475, 'Что такое CSS Houdini?', 'Набор низкоуровневых API, дающих разработчикам доступ к движку рендеринга браузера для создания собственных свойств и анимаций.', 2, 6, 54, 4, 3, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(476, 'Как работают градиенты в качестве масок (mask-image)?', 'Позволяют скрывать части элемента, используя градиент (от прозрачного к черному), создавая эффект плавного исчезновения.', 2, 6, 54, 4, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(477, 'Что такое Mix Blend Mode?', 'Определяет, как цвета элемента смешиваются с фоном под ним (аналог режимов Multiply, Screen в Photoshop).', 2, 6, 54, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(478, 'Как оптимизировать загрузку шрифтов?', 'Использовать font-display: swap (чтобы текст был виден сразу в системном шрифте) и предварительную загрузку preload.', 2, 6, 55, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(479, 'Почему селектор * { box-sizing: border-box; } считается стандартом?', 'Потому что он делает расчеты размеров интуитивными: если задано width: 100px, блок всегда будет 100px, независимо от паддингов.', 2, 6, 55, 1, 1, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(480, 'Что такое \"Критический CSS\" (Critical CSS)?', 'Техника выделения минимального набора стилей для верхней части экрана (Above the fold) и встраивание их прямо в HTML для мгновенной отрисовки.', 2, 6, 55, 4, 3, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(481, 'Как бороться с \"Дребезгом\" (Layout Shift) при загрузке?', 'Задавать фиксированные размеры для картинок и рекламных блоков заранее, чтобы контент не \"прыгал\" после их загрузки.', 2, 6, 55, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(482, 'Альтернатива display: none для скринридеров?', 'Класс visually-hidden: он скрывает элемент визуально (через clip или абсолют вне экрана), но оставляет его доступным для программ чтения.', 2, 6, 55, 3, 2, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(483, 'Зачем нужны вендорные префиксы (-webkit-, -moz-)?', 'Для поддержки экспериментальных свойств в старых версиях браузеров до того, как они стали официальным стандартом.', 2, 6, 55, 2, 1, 0, 1, '2026-05-13 10:36:44', '2026-05-13 10:36:44'),
(484, 'Что такое SQL?', 'Structured Query Language — язык для управления данными в реляционных БД (создание, чтение, обновление, удаление).', 3, 7, 60, 1, 1, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(485, 'Разница между DDL и DML?', 'DDL (Data Definition) — команды структуры (CREATE, ALTER, DROP). DML (Data Manipulation) — команды данных (SELECT, INSERT, UPDATE, DELETE).', 3, 7, 60, 2, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(486, 'Разница между DELETE и TRUNCATE?', 'DELETE удаляет строки по одной (можно с WHERE, медленно, логируется). TRUNCATE очищает всю таблицу мгновенно (нельзя WHERE, не возвращает место сразу).', 3, 7, 60, 2, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(487, 'Что такое NULL в SQL?', 'Специальное значение, означающее \"отсутствие данных\" или \"неизвестное значение\". NULL не равен нулю или пустой строке.', 3, 7, 60, 1, 1, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(488, 'Разница между CHAR и VARCHAR?', 'CHAR — фиксированная длина (дополняется пробелами). VARCHAR — переменная длина (хранит ровно столько, сколько ввели + 1-2 байта на длину).', 3, 7, 60, 2, 1, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(489, 'Что такое Первичный ключ (Primary Key)?', 'Поле или набор полей, которые уникально идентифицируют каждую строку. Не может содержать NULL и дубликаты.', 3, 7, 61, 1, 1, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(490, 'Что такое Внешний ключ (Foreign Key)?', 'Поле в одной таблице, которое ссылается на Primary Key в другой. Обеспечивает ссылочную целостность данных.', 3, 7, 61, 2, 1, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(491, 'Разница между INNER JOIN и LEFT JOIN?', 'INNER возвращает только те строки, для которых есть соответствие в обеих таблицах. LEFT возвращает ВСЕ строки из левой таблицы и совпадения из правой.', 3, 7, 61, 2, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(492, 'Что такое Self-Join?', 'Операция, при которой таблица объединяется сама с собой (например, чтобы найти сотрудников и их менеджеров в одной таблице).', 3, 7, 61, 3, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(493, 'Как реализовать связь \"Многие-ко-многим\"?', 'Через третью промежуточную таблицу (таблицу-связку), которая содержит внешние ключи на обе основные таблицы.', 3, 7, 61, 2, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(494, 'Разница между WHERE и HAVING?', 'WHERE фильтрует строки ДО группировки. HAVING фильтрует результаты ПОСЛЕ группировки и работы агрегатных функций.', 3, 7, 62, 2, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(495, 'Назовите основные агрегатные функции.', 'COUNT (количество), SUM (сумма), AVG (среднее), MAX (максимум), MIN (минимум).', 3, 7, 62, 1, 1, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(496, 'Что делает оператор GROUP BY?', 'Группирует строки с одинаковыми значениями в указанных столбцах для выполнения вычислений над ними (агрегации).', 3, 7, 62, 2, 1, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(497, 'Как удалить дубликаты в SELECT?', 'С помощью ключевого слова DISTINCT сразу после SELECT.', 3, 7, 62, 1, 1, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(498, 'Что такое CTE (Common Table Expression)?', 'Временный результирующий набор, определяемый через WITH. Повышает читаемость сложных запросов и поддерживает рекурсию.', 3, 7, 63, 3, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(499, 'Разница между коррелированным и обычным подзапросом?', 'Обычный выполняется один раз. Коррелированный ссылается на поля внешнего запроса и выполняется для каждой его строки (медленнее).', 3, 7, 63, 3, 3, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(500, 'Что такое VIEW (Представление)?', 'Виртуальная таблица, представляющая собой сохраненный SQL-запрос. Упрощает доступ к сложным данным и ограничивает доступ к полям.', 3, 7, 63, 3, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(501, 'Что такое Оконные функции (Window Functions)?', 'Функции (OVER), выполняющие вычисления над набором строк, связанных с текущей строкой, не сворачивая их в одну группу (в отличие от GROUP BY).', 3, 7, 63, 4, 3, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(502, 'Что такое ACID?', '4 свойства транзакции: Atomicity (Атомарность), Consistency (Согласованность), Isolation (Изолированность), Durability (Долговечность).', 3, 7, 64, 3, 3, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(503, 'Разница между COMMIT и ROLLBACK?', 'COMMIT фиксирует изменения транзакции навсегда. ROLLBACK отменяет все действия текущей транзакции, возвращая базу в исходное состояние.', 3, 7, 64, 3, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(504, 'Что такое Уровни изоляции транзакций?', 'Настройки, определяющие, как изменения, сделанные одной транзакцией, видны другим. (Read Uncommitted, Read Committed, Repeatable Read, Serializable).', 3, 7, 64, 4, 3, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(505, 'Как индексы влияют на производительность?', 'Ускоряют поиск данных (чтение), но замедляют запись (INSERT/UPDATE), так как индексы нужно перестраивать.', 3, 7, 65, 3, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(506, 'Что такое SQL-инъекция?', 'Атака, при которой злоумышленник внедряет вредоносный SQL-код в запрос через поля ввода. Защита — использование Prepared Statements.', 3, 7, 65, 3, 2, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(507, 'Зачем нужен EXPLAIN?', 'Команда, показывающая план выполнения запроса: какие индексы используются, как объединяются таблицы. Помогает найти \"узкие места\".', 3, 7, 65, 4, 3, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(508, 'Что такое Нормализация?', 'Процесс организации БД для исключения дублирования данных и обеспечения целостности (1NF, 2NF, 3NF).', 3, 7, 65, 2, 3, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(509, 'Что такое Триггер?', 'Хранимая процедура, которая автоматически выполняется сервером при возникновении определенного события (INSERT, UPDATE, DELETE).', 3, 7, 65, 4, 3, 0, 1, '2026-05-13 10:40:37', '2026-05-13 10:40:37'),
(510, 'В чем разница между UNION и UNION ALL?', 'UNION объединяет результаты и УДАЛЯЕТ дубликаты (что требует времени на сортировку). UNION ALL просто склеивает результаты, сохраняя все строки, и работает быстрее.', 3, 7, 60, 2, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(511, 'Что такое оператор CASE?', 'Это аналог if-else в SQL. Позволяет выводить разные значения в зависимости от условий прямо внутри SELECT или ORDER BY.', 3, 7, 60, 2, 1, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(512, 'Как работает оператор LIKE и символы % и _?', 'LIKE используется для поиска по шаблону. % заменяет любое количество символов, а _ — ровно один символ.', 3, 7, 60, 1, 1, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(513, 'Что такое первичный ключ (Composite Key)?', 'Составной первичный ключ — это комбинация из нескольких столбцов, которая вместе уникально идентифицирует строку.', 3, 7, 60, 2, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(514, 'Что такое FULL OUTER JOIN?', 'Возвращает все записи из обеих таблиц. Если совпадения нет, подставляет NULL в пустые поля другой таблицы.', 3, 7, 61, 3, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(515, 'Что такое CROSS JOIN?', 'Перекрестное соединение: каждая строка первой таблицы соединяется с каждой строкой второй (декартово произведение).', 3, 7, 61, 2, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(516, 'В чем смысл \"Ссылочной целостности\" (Referential Integrity)?', 'Правило, гарантирующее, что связи между таблицами остаются корректными: нельзя создать внешний ключ на несуществующий первичный или удалить Primary Key, на который ссылаются.', 3, 7, 61, 3, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(517, 'Разница между RANK(), DENSE_RANK() и ROW_NUMBER()?', 'ROW_NUMBER дает уникальный номер каждой строке. RANK дает одинаковый номер равным значениям, пропуская следующие числа. DENSE_RANK не делает пропусков в нумерации.', 3, 7, 63, 3, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(518, 'Что такое Рекурсивный CTE?', 'Запрос, который ссылается на самого себя. Используется для работы с иерархиями (например, дерево категорий или структура компании).', 3, 7, 63, 4, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(519, 'Зачем нужны функции LEAD() и LAG()?', 'Это оконные функции доступа: LAG берет значение из предыдущей строки, LEAD — из следующей. Полезно для сравнения показателей по датам.', 3, 7, 63, 3, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(520, 'Что такое \"Фантомное чтение\" (Phantom Read)?', 'Ситуация, когда при повторном чтении в транзакции появляются новые строки, добавленные другой транзакцией в этот период.', 3, 7, 64, 4, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(521, 'Что такое \"Грязное чтение\" (Dirty Read)?', 'Чтение данных, которые были изменены другой транзакцией, но еще не зафиксированы (COMMIT).', 3, 7, 64, 3, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(522, 'Как работает Deadlock в БД?', 'Взаимная блокировка: Транзакция А ждет ресурс, занятый Б, а Б ждет ресурс, занятый А. БД обычно сама обрывает одну из них.', 3, 7, 64, 4, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(523, 'Зачем нужен SAVEPOINT?', 'Позволяет откатить транзакцию не полностью (через ROLLBACK), а до определенной точки внутри неё.', 3, 7, 64, 3, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(524, 'Разница между Кластерным и Некластерным индексом?', 'Кластерный определяет физический порядок хранения данных на диске (один на таблицу). Некластерный — это отдельная структура со ссылками на данные.', 3, 7, 65, 4, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(525, 'Что такое Покрывающий индекс (Covering Index)?', 'Индекс, который содержит все поля, необходимые для запроса. БД берет данные прямо из индекса, не обращаясь к самой таблице.', 3, 7, 65, 4, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(526, 'Что такое Селективность индекса?', 'Показатель уникальности значений в столбце. Чем выше селективность (больше уникальных значений), тем эффективнее работает индекс.', 3, 7, 65, 4, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(527, 'В чем разница между хранимой процедурой и функцией?', 'Процедура выполняет действия и может не возвращать результат. Функция всегда возвращает значение и её можно использовать внутри SELECT.', 3, 7, 65, 3, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(528, 'Как работают команды GRANT и REVOKE?', 'GRANT выдает права доступа пользователю (на чтение, запись и т.д.). REVOKE — отзывает эти права.', 3, 7, 65, 3, 2, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15'),
(529, 'Что такое B-Tree индекс?', 'Сбалансированное дерево — стандартная структура индекса в большинстве БД. Позволяет искать данные за логарифмическое время O(log n).', 3, 7, 65, 4, 3, 0, 1, '2026-05-13 10:41:15', '2026-05-13 10:41:15');
